INSERT INTO `cards` (`ind`, `name`, `ukid`, `code`, `release_id`, `element_id`, `price`, `power`, `elite`, `single`, `class`, `type`, `rarity`, `prop`, `health`, `move`, `strike_weak`, `strike_medium`, `strike_strong`, `descr`) VALUES
(1, 'Кочевник', 's1_1', '9d579', 1, 1, 3, 4, 0, 0, '', 'creature', 'common', NULL, 8, 2, 1, 2, 3, ''),
(2, 'Кшар', 's1_2', '7a98b', 1, 1, 3, 4, 0, 0, '', 'creature', 'common', '{\"ability\": {\"value\": 1, \"element\": \"mountains\"}, \"actions\": [{\"type\": \"uchr\", \"value\": 1}, {\"near\": true, \"type\": \"tap\", \"coins\": 1, \"value\": 3}], \"save_coins\": true}', 6, 2, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\r\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Особый удар «молниеносный выпад» на 3.<br />\r\n+1 к ударам по горным.'),
(3, 'Волхв', 's1_3', '6bce4', 1, 1, 4, 3, 0, 0, 'Орк', 'creature', 'common', '{\"start\": {\"side\": 2, \"type\": \"get_coins\", \"coins\": 1}, \"actions\": [{\"key\": \"volkhvovanie\", \"name\": \"Волхвование при луне\", \"type\": \"wound_transfer\", \"coins\": 1, \"on_finish\": \"main_phase\", \"donor_filter\": \"wounded\", \"max_transfer\": 2, \"target_filter\": \"enemy\"}], \"save_coins\": true}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «волхвование при луне» — перераспределить 2 (или менее) раны с существа в вашем отряде на существо или существ противника.<br />\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(4, 'Гиррит', 's1_4', '9c2e4', 1, 1, 4, 5, 0, 1, '', 'creature', 'rare', '{\"actions\": [{\"key\": \"shot1\", \"type\": \"shot\", \"range\": 3, \"value\": 1}, {\"key\": \"shot2\", \"type\": \"shot\", \"coins\": 1, \"value\": 2, \"marker\": {\"type\": \"hunt\", \"bonus\": 2, \"expire\": 1}}], \"save_coins\": true}', 8, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1, дальность 3.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 2.<br />\nПри выстреле атакованная карта получает маркер «охоты» до конца вашего хода (когда она получает раны от атаки летающего существа — ранить ее еще на 2 и удалить маркер).'),
(5, 'Ост', 's1_5', '38d89', 1, 1, 4, 4, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"type\": \"discharge\", \"value\": 1}], \"instants\": [{\"key\": \"dar_sily\", \"name\": \"Дар силы\", \"effect\": {\"mode\": \"set\", \"type\": \"strike_level\", \"value\": \"strong\"}, \"trigger\": \"combat\", \"phase\": \"power\"}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «дар силы» — свести <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> вашего существа к сильному.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.'),
(6, 'Пустотник', 's1_6', 'ac67c', 1, 1, 4, 4, 0, 1, 'Тоа-Дан', 'creature', 'common', '{\"coins\": {\"cast\": {\"mode\": \"shield\", \"spend\": \"choice\", \"value\": 1, \"max_value\": 3, \"min_value\": 1}, \"max_value\": 3}, \"actions\": [{\"key\": \"shield_light\", \"name\": \"Щит света\", \"type\": \"cast\", \"target\": \"ally_other\"}, {\"type\": \"discharge\", \"value\": 1}], \"save_coins\": true, \"coins_receive_deny\": true}', 9, 1, 1, 1, 2, 'X<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «шит света» — другое существо получает защиту от всех немагических атак на X ходов противника. Не может иметь больше 3<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> и получать <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> от других существ.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.'),
(7, 'Смотритель стойла', 's1_7', '8c84e', 1, 1, 4, 3, 0, 1, 'Аккениец', 'creature', 'uncommon', '{\"on_move\": [{\"stat\": \"ova\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\"}], \"turn_start\": [{\"type\": \"whip\", \"label\": \"Щелчок хлыста\", \"value\": 1}]}', 8, 2, 2, 2, 3, 'В начале вашего хода может ранить себя или стоящее рядом существо на 1, при этом цель получает +1<img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\"> до конца вашего хода (воздействие «щелчок хлыста»).<br />\nПри перемещении на соседнюю клетку получает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 или +1 к <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\"> до конца вашего хода.'),
(8, 'Степной волколак', 's1_8', '906bc', 1, 1, 4, 4, 0, 0, '', 'creature', 'uncommon', '{\"ova\": {\"value\": 1}, \"zoo\": true, \"on_death\": [{\"type\": \"tap\", \"value\": 2, \"target\": \"near\"}], \"regeneration\": {\"value\": 1}, \"strike_reduction\": {\"medium\": \"weak\", \"strong\": \"weak\"}}', 7, 2, 2, 2, 3, 'Все <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по Степному волколаку сводятся к слабым.<br />\nПри гибели — особый удар на 2.'),
(9, 'Хозяйка прайда', 's1_9', 'a7fd8', 1, 1, 4, 5, 0, 1, 'Тоа-Дан', 'creature', 'common', '{\"actions\": [{\"key\": \"sand_claws\", \"name\": \"Песчаные когти\", \"type\": \"sand_claws\", \"value\": 1}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «песчаные когти» — ранить существо на 1, ваши существа получают +1 к броскам кубика при атаках по этому существу до конца хода.'),
(10, 'Аколит Дзара', 's1_10', 'af4b7', 1, 1, 5, 3, 0, 1, 'Тоа-Дан', 'creature', 'common', '{\"actions\": [{\"key\": \"triple_discharge\", \"name\": \"Тройной разряд\", \"type\": \"multi_discharge\", \"value\": 1, \"filter\": \"enemy\", \"max_targets\": 3}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Три или менее разряда на 1 по разным существам.'),
(11, 'Змееглав', 's1_11', 'f8d6f', 1, 1, 5, 4, 0, 0, '', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"ovz\": {\"value\": 1}, \"actions\": [{\"type\": \"uchr\", \"value\": 1}]}', 9, 1, 2, 4, 5, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.'),
(12, 'Кабаний наездник', 's1_12', 'fa263', 1, 1, 5, 5, 0, 0, 'Орк', 'creature', 'uncommon', '{\"on_move_half\": [{\"to\": \"enemy\", \"from\": \"own\", \"modifiers\": [{\"stat\": \"ability_strike\", \"value\": 1, \"expire\": \"end_of_turn\"}]}, {\"to\": \"own\", \"from\": \"enemy\", \"flags\": [\"no_close_this_turn\"]}]}', 11, 1, 2, 3, 4, 'После перемещения с вашей половины поля боя на половину поля боя противника получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца хода.<br />\nПосле перемещения с половины поля боя противника на вашу половину поля боя получает «Не закрывается при атаке» до конца хода.'),
(13, 'Орк', 's1_13', 'bb8b4', 1, 1, 5, 3, 0, 0, 'Орк', 'creature', 'common', '{\"direct\": {\"check\": true, \"element\": \"mountains\"}, \"ability\": {\"only\": [\"strike\"], \"value\": 1, \"element\": \"mountains\"}}', 10, 1, 3, 3, 4, '+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> по горным существам.'),
(14, 'Пустынный кондор', 's1_14', 'db9f1', 1, 1, 5, 3, 0, 0, '', 'fly', 'uncommon', '{\"actions\": [{\"key\": \"dive\", \"name\": \"Пикирование\", \"type\": \"dive\", \"coins\": 1, \"strike\": {\"weak\": 3, \"medium\": 4, \"strong\": 4}, \"once_per_battle\": true}], \"save_coins\": true}', 8, 0, 2, 3, 3, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «пикирование» — переместить нелетающее существо противника на соседнюю клетку; потерять полет, получить <img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\">1 и переместиться на клетку, которую занимало это существо, при этом ранить его на 3-4-4 (1 раз за бой).'),
(15, 'Рубаки Холверта', 's1_15', 'e21b4', 1, 1, 5, 4, 0, 1, 'Аккениец', 'creature', 'uncommon', '{\"has_line\": true, \"on_successful_strike\": {\"key\": \"holvert_open\", \"type\": \"open_line_ally_cannot_attack\", \"uses_per_turn\": 1}}', 10, 1, 2, 3, 4, 'Строй: при <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — открыть существо в строю с Рубаками Холверта; оно не может атаковать до конца хода (1 раз за ход).'),
(16, 'Санкторум', 's1_16', 'd585e', 1, 1, 5, 4, 0, 0, 'Аккениец', 'creature', 'common', '{\"ability\": {\"line\": true, \"only\": [\"strike\"], \"level\": [\"weak\"], \"value\": 1}, \"block_weak_strike\": true}', 10, 1, 1, 2, 3, 'Защита от слабых <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.<br />\nСтрой: +1 к слабому <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(17, 'Арбалетчик', 's1_17', 'c25b8', 1, 1, 6, 4, 0, 0, 'Аккениец', 'creature', 'common', '{\"zot\": {\"line\": true}, \"coins\": {\"shot\": {\"spend\": \"all\", \"value\": 2}, \"max_value\": 4}, \"actions\": [{\"type\": \"shot\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 3}}], \"save_coins\": true}', 8, 1, 1, 2, 3, 'Строй: <img src=\"/images/icons/icon-zot.png\" class=\"img-fluid\" alt=\"zot\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1-2-3.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n+2 к выстрелу за каждую <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> на Арбалетчике. При выстреле теряет все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. Не может иметь более 4<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">'),
(18, 'Килсус', 's1_18', 'bcd13', 1, 1, 6, 5, 0, 0, '', 'creature', 'uncommon', '{\"ova\": {\"value\": 1}, \"execute\": 0, \"on_move\": [{\"stat\": \"execute\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\"}], \"block_strike_answer\": true}', 11, 2, 2, 3, 4, 'Не получает ран от ответных ударов.<br />\nПри <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — добивание на X (не более 2 раз за ход), где X — количество клеток, на которое передвинулся Килсус в этот ход.'),
(19, 'Щитоносец', 's1_19', 'd020e', 1, 1, 7, 5, 0, 0, 'Аккениец', 'creature', 'uncommon', '{\"damage_reduction\": [{\"types\": [\"shot\", \"throw\", \"discharge\", \"uchr\"], \"value\": 1}, {\"line\": true, \"types\": [\"strike\"], \"value\": 1}], \"aura_plains_ranged\": {\"types\": [\"shot\", \"throw\", \"discharge\", \"uchr\"], \"value\": 1}}', 10, 1, 1, 2, 3, '-1 от дальних атак.<br />\nПока ваше степное существо стоит справа или слева от Щитоносца, оно получает -1 от дальних атак.<br />\nСтрой: -1 от <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(20, 'Глорм', 's1_20', 'bbfd7', 1, 1, 4, 3, 1, 0, 'Тоа-Дан', 'creature', 'common', '{\"instants\": [{\"key\": \"flash\", \"name\": \"Отвлекающая вспышка\", \"effect\": {\"type\": \"damage_cap\", \"value\": 1, \"self_wound\": 1, \"except_element\": \"plains\"}, \"trigger\": \"combat\", \"phase\": \"setter\"}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «отвлекающая вспышка» — свести ближний удар по существу в вашем отряде к 1, при этом ранить Глорма на 1 (или на 0, если удар нанесен по степному существу).'),
(21, 'Мантикора', 's1_21', 'a0318', 1, 1, 4, 4, 1, 1, '', 'fly', 'uncommon', '{\"zoz\": true, \"direct\": {\"check\": true, \"types\": [\"magic\", \"cast\", \"discharge\"]}, \"ignore\": [\"zoa\", \"zoal\"], \"ability\": {\"types\": [\"magic\", \"cast\", \"discharge\"], \"value\": 1}}', 7, 0, 2, 2, 3, 'Игнорирует <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.<br />\r\n+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> по существам, обладающим разрядом, магическим ударом или заклинанием.'),
(22, 'Орк-бомбардир', 's1_22', 'd6acb', 1, 1, 4, 2, 1, 0, 'Орк', 'creature', 'common', '{\"actions\": [{\"key\": \"bomb\", \"name\": \"Бомба\", \"type\": \"bomb_shot\", \"range\": 3, \"value\": 1, \"bomb_damage\": 2}]}', 10, 1, 2, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «бомбы» на 1 по карте на выбранной клетке, дальность 3; в начале вашего следующего хода все карты на этой клетке ранятся на 2 (воздействие «взрыв»).'),
(23, 'Риала', 's1_23', 'e2651', 1, 1, 4, 3, 1, 0, 'Аккениец', 'creature', 'common', '{\"movement_direction_bonus\": {\"expire\": \"end_of_turn\", \"same_direction\": {\"moves\": 2, \"modifier\": {\"stat\": \"direct\", \"value\": true}}, \"different_directions\": {\"count\": 2, \"modifier\": {\"stat\": \"ova\", \"value\": 2}}}}', 8, 2, 2, 3, 4, 'Получает <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> до конца вашего хода, если переместилась хотя бы на 2 клетки в одном и том же направлении в этот ход.<br />\nПолучает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">2 до конца вашего хода, если переместилась хотя бы на 2 клетки в разных направлениях в этот ход.'),
(24, 'Посвященный Дзара', 's1_24', 'b68c8', 1, 1, 5, 3, 1, 0, 'Тоа-Дан', 'creature', 'common', '{\"zor\": true, \"actions\": [{\"type\": \"discharge\", \"range\": 1, \"strike\": {\"weak\": 2, \"medium\": 3, \"strong\": 4}}], \"on_move\": [{\"stat\": \"action_range\", \"type\": \"modifier\", \"types\": [\"discharge\"], \"value\": 1, \"expire\": \"end_of_turn\"}]}', 9, 2, 1, 1, 2, 'При перемещении на соседнюю клетку получает +1 к дальности разряда до конца хода.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 2-3-4, дальность 1.'),
(25, 'Хронос', 's1_25', 'b2294', 1, 1, 5, 4, 1, 1, 'Тоа-Дан', 'creature', 'rare', '{\"actions\": [{\"key\": \"give_coin\", \"name\": \"Передать монету\", \"type\": \"give_coin\", \"coins\": 1, \"target\": \"ally_other\"}], \"instants\": [{\"key\": \"time_return\", \"name\": \"Возврат во времени\", \"coins\": 1, \"effect\": {\"type\": \"heal_turn_wounds\"}, \"target\": \"ally\", \"trigger\": \"turn\"}], \"save_coins\": true}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «возврат во времени» — излечить другое существо от ран, полученных в этот ход.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Ваше существо получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(26, 'Анубисар', 's1_26', 'bf251', 1, 1, 6, 5, 1, 1, '', 'creature', 'rare', '{\"strike_effects\": [{\"levels\": [\"strong\"], \"chain_damage\": {\"value\": 1, \"filter\": \"enemy\", \"max_targets\": 2}}]}', 12, 2, 2, 3, 5, '[Эррата 2023.04.08]<br />\r\nПри сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> ранить на 1 двух существ противника, стоящих рядом с атакованным (воздействие «цепи Анубисара»).<br />\r\nСтрой: Анубисар получает бонусы строя всех степных существ, с которыми стоит в строю (меняя название карты в тексте особенности на «Анубисар»).'),
(27, 'Бон и Берроу', 's1_27', 'e119d', 1, 1, 6, 5, 1, 1, 'Аккениец, Тоа-Дан', 'creature', 'rare', '{\"ova\": true, \"armor\": {\"value\": 1}, \"has_armor\": true}', 8, 2, 2, 3, 4, 'Пока на Бон и Берроу нет <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> — получает «<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 2, при этом может получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">».<br />\nПока на Бон и Берроу есть <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> — получает «При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — разряд на 1-2-2, дальность 3».<br />\nЕсли Бон и Берроу атакованы <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — могут потерять <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">; блокировать удар. Не может иметь более 1 <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(28, 'Матриарх племени', 's1_28', 'aa945', 1, 1, 6, 4, 1, 1, 'Орк', 'creature', 'ultrarare', NULL, 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «приказ матриарха» — все ваши существа, стоящие рядом с выбранным существом противника, сражаются с ним как с открытым, не закрываясь при этом.<br />\r\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(29, 'Пеший латник', 's1_29', 'bcd84', 1, 1, 6, 4, 1, 0, 'Аккениец', 'creature', 'common', '{\"zov\": true, \"armor\": {\"line\": true, \"check\": true, \"value\": 2}, \"check\": [\"armor\"], \"answer\": {\"type\": \"tap\", \"types\": [\"strike\", \"tap\", \"magic\"], \"value\": 2}, \"has_line\": true, \"has_armor\": true}', 12, 1, 2, 2, 3, 'Строй: <img src=\"/images/icons/icon-armor.png\" class=\"img-fluid\" alt=\"armor\">2.<br />\nПри ближнем ударе по Пешему латнику — особый удар на 2 по атаковавшему.'),
(30, 'Бронтобей', 's1_30', 'c5bd7', 1, 1, 7, 4, 1, 0, '', 'creature', 'rare', '{\"ova\": {\"value\": 2}, \"direct\": true, \"ability\": {\"value\": 1, \"position\": \"opposite\"}, \"on_move\": [{\"stat\": \"ability_strike\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\"}]}', 13, 2, 2, 2, 3, 'При перемещении на соседнюю клетку получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца хода.<br />\n+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по существам напротив Бронтобея.'),
(31, 'Ойуун', 's1_31', 'ab193', 1, 1, 7, 4, 1, 1, '', 'creature', 'ultrarare', '{\"zov\": true, \"actions\": [{\"key\": \"gain_zoal\", \"name\": \"Получить ЗОАЛ\", \"prop\": \"zoal\", \"self\": true, \"type\": \"grant_prop\"}], \"instants\": [{\"key\": \"battle_frenzy\", \"name\": \"Боевое исступление\", \"effect\": {\"type\": \"open\", \"damage\": 1, \"condition\": \"target_closed\"}, \"target\": \"ally\", \"trigger\": \"turn\", \"uses_per_turn\": 2}]}', 7, 1, 1, 1, 1, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.<br />\n<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «боевое исступление» — открыть ваше существо, при этом ранить его на 1 (не более 2 раз за ход).'),
(32, 'Дегаска', 's1_32', '7c0fe', 1, 1, 7, 5, 1, 1, 'Орк', 'creature', 'ultrarare', NULL, 13, 2, 2, 3, 5, '-1 от дальних атак.<br />\nВ начале боя и при каждом сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> покажите из колоды существо (кроме Дегаски; карту с каждым названием можно показывать только один раз) с особенностью с текстом «при сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">» — Дегаска получает эту особенность до конца боя, меняя название карты в тексте особенности на «Дегаска».'),
(33, 'Скелос', 's1_33', 'ea501', 1, 1, 8, 4, 1, 0, '', 'creature', 'common', '{\"ova\": {\"value\": 2}, \"zom\": true, \"zoal\": {\"line\": true}, \"ability\": {\"value\": 1, \"condition\": \"enemy_front_row_empty\"}, \"damage_reduction\": [{\"types\": [\"strike\", \"tap\", \"uchr\", \"shot\", \"throw\"], \"value\": 2, \"attacker_direct\": true}], \"can_attack_flying\": {\"condition\": \"enemy_front_row_empty\"}}', 13, 1, 3, 4, 5, '-2 от направленных ударов.<br />\nСтрой: <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.<br />\nПока в первом ряду противника нет его карт, получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и может атаковать летающих <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(34, 'Минотавр', 's1_34', 'd7555', 1, 1, 9, 5, 1, 0, '', 'creature', 'rare', '{\"armor\": {\"value\": 2}, \"ability\": {\"line\": true, \"only\": [\"strike\"], \"level\": [\"strong\"], \"value\": 1}, \"attacks_per_turn\": 2}', 14, 2, 3, 4, 5, 'Может атаковать <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> 2 раза за ход, после первой атаки не закрывается.<br />\nСтрой: +1 к сильному <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(35, 'Гном-поджигатель', 's1_35', 'faf95', 1, 2, 3, 4, 0, 0, 'Гном', 'creature', 'common', '{\"turn_start\": [{\"type\": \"damage\", \"label\": \"Нестерпимый жар\", \"value\": 1, \"target\": \"opposite\", \"value_if_not_moved\": 2}]}', 7, 1, 1, 1, 2, 'В начале вашего хода воздействие «нестерпимый жар» — ранить существо противника напротив Гнома-поджигателя на 1 (+1 к воздействию, если это существо не двигалось в прошлый ход противника).'),
(36, 'Ледяной змей', 's1_36', 'e847a', 1, 2, 3, 4, 0, 1, 'Дракон', 'fly', 'common', '{\"strike_effects\": [{\"levels\": [\"weak\", \"medium\", \"strong\"], \"grant_ally_modifier\": {\"filter\": \"has_magic\", \"modifier\": {\"stat\": \"damage_reduction\", \"types\": [\"strike\", \"tap\", \"uchr\", \"shot\", \"throw\"], \"value\": 1, \"expire\": \"end_of_opponent_turn\"}}}]}', 6, 0, 1, 2, 3, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — ваше существо, обладающее разрядом, магическим ударом или заклинанием, получает -1 от немагических атак до конца следующего хода противника (воздействие «каменная кожа»).'),
(37, 'Овражный гном', 's1_37', 'abadc', 1, 2, 3, 4, 0, 0, 'Гном', 'creature', 'common', '{\"direct\": true, \"ability\": [{\"only\": [\"strike\"], \"value\": 1, \"closed\": true}], \"strike_effects\": [{\"levels\": [\"weak\", \"medium\", \"strong\"], \"close_or_damage\": {\"damage\": 2, \"condition\": \"target_open\"}}]}', 6, 1, 1, 1, 2, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по открытому существу — воздействие «адское зловоние» — это существо должно закрыться либо получить 2 раны (по выбору атакованного).<br />\n+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по закрытым существам.'),
(38, 'Бешеный маг', 's1_38', 'd80d1', 1, 2, 4, 5, 0, 0, 'Линунг', 'creature', 'common', '{\"actions\": [{\"type\": \"discharge\", \"value\": 1, \"range\": 3}], \"instants\": [{\"key\": \"magic_trick\", \"name\": \"Магический трюк\", \"effect\": {\"type\": \"redirect_strike\"}, \"target\": \"adjacent_ally\", \"trigger\": \"combat\", \"phase\": \"redirect\"}]}', 7, 1, 1, 2, 3, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «магический трюк» — перенаправить <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> с карты на стоящее рядом с ней существо в вашем отряде.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1, дальнность 3.'),
(39, 'Гуль', 's1_39', 'cc075', 1, 2, 4, 5, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"type\": \"uchr\", \"value\": 1}, {\"near\": true, \"type\": \"execute\", \"value\": 2}], \"deadeat\": true}', 8, 2, 1, 2, 3, 'Трупоедство.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Добивание на 2.'),
(40, 'Мразень', 's1_40', 'b6724', 1, 2, 4, 3, 0, 0, '', 'creature', 'common', '{\"ability\": {\"prop\": [\"ova\", \"ovz\", \"armor\"], \"value\": 1}, \"actions\": [{\"type\": \"throw\", \"range\": 3, \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}}]}', 7, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «сосульки» на 1-2-2, дальность 3.<br />\n+1 к метанию по картам, обладающим <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">, <img src=\"/images/icons/icon-ovz.png\" class=\"img-fluid\" alt=\"ovz\"> или <img src=\"/images/icons/icon-armor.png\" class=\"img-fluid\" alt=\"armor\">.'),
(41, 'Айрин', 's1_41', 'b62d0', 1, 2, 5, 5, 0, 1, 'Линунг', 'creature', 'common', '{\"zor\": true, \"actions\": [{\"type\": \"discharge\", \"value\": 1}], \"airin_trigger\": true}', 8, 1, 1, 1, 2, 'Когда существо с магической способностью, не стоявшее рядом с Айрин, перемещается на соседнюю с ней клетку — получить +1 к разряду до конца вашего хода (до 2 раз в ход).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.'),
(42, 'Знахарь племени', 's1_42', 'fbe47', 1, 2, 5, 4, 0, 0, 'Йордлинг', 'creature', 'common', '{\"coins\": {\"max_value\": 3}, \"actions\": [{\"key\": \"revive\", \"name\": \"Возродить\", \"type\": \"revive\", \"coins\": 3, \"once_per_battle\": true}, {\"type\": \"discharge\", \"value\": 1}], \"valhalla\": [{\"type\": \"damage\", \"value\": 1, \"target\": \"own_creature\"}, {\"type\": \"get_coins\", \"value\": 1, \"target\": \"own_creature\"}], \"save_coins\": true}', 8, 1, 1, 2, 3, '3<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Возродить существо (в закрытом виде, 1 раз за бой).<br />\nВальхалла: ранить ваше существо на 1, при этом оно получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.'),
(43, 'Каменный голем', 's1_43', 'be2f2', 1, 2, 5, 5, 0, 0, '', 'creature', 'uncommon', '{\"clumsy\": 1, \"damage_reduction\": [{\"types\": [\"strike\", \"tap\", \"uchr\", \"shot\", \"throw\"], \"value\": 2}]}', 8, 1, 3, 4, 5, 'Неповоротливость.<br />\n-2 от немагических атак.'),
(44, 'Страж чертогов', 's1_44', 'e2f8a', 1, 2, 5, 4, 0, 0, 'Гном', 'creature', 'common', '{\"armor\": {\"value\": 1}, \"direct\": {\"check\": true, \"condition\": \"line_count_2_plus\"}, \"has_line\": true, \"strike_range_line\": 2}', 8, 1, 2, 3, 3, 'Строй: Может объявлять <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> с дальностью 2.<br />\nПока стоит в строю с хотя бы двумя существами, имеет <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\">.'),
(45, 'Ледовый охотник', 's1_45', 'b24da', 1, 2, 5, 4, 0, 0, 'Йордлинг', 'creature', 'common', '{\"actions\": [{\"type\": \"uchr\", \"value\": 2, \"apply_to_mid\": [{\"stat\": \"ova\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\"}]}], \"valhalla\": [{\"stat\": \"ova\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\", \"target\": \"own_creature\"}]}', 7, 2, 1, 2, 3, '<img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 2, при этом существо напротив Ледового охотика получает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 или +1 к <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\"> до конца вашего хода.<br />\nВальхалла: ваше существо получает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 или +1 к <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\"> до конца вашего хода'),
(46, 'Мастер топора', 's1_46', 'b9382', 1, 2, 5, 4, 0, 0, 'Гном', 'creature', 'common', '{\"armor\": {\"value\": 1}, \"coins\": {\"magic\": {\"spend\": \"choice\", \"value\": 1, \"max_value\": 5}}, \"actions\": [{\"type\": \"magic\", \"strike\": {\"weak\": 0, \"medium\": 1, \"strong\": 2}}], \"save_coins\": true, \"turn_start\": [{\"line\": true, \"type\": \"get_coins\", \"coins\": 1}]}', 10, 1, 2, 3, 3, 'Строй: в начале вашего хода Мастер топора получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. X<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 0-1-2, +1 к удару за каждую потраченную <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(47, 'Ртунх', 's1_47', 'afc4b', 1, 2, 5, 4, 0, 1, '', 'fly', 'common', '{\"ovz\": 1, \"ability\": {\"value\": 1, \"element\": \"swamps\"}, \"fly_defend\": true, \"damage_reduction\": [{\"types\": [\"shot\", \"throw\", \"discharge\"], \"value\": 1}]}', 9, 0, 1, 2, 2, '-1 от дальних атак.<br />\r\n+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по болотным.<br />\r\nМожет выступать защитником любому вашему нелетающему существу.'),
(48, 'Смотритель горнила', 's1_48', 'e49c4', 1, 2, 5, 5, 0, 0, 'Гном', 'creature', 'common', '{\"ovz\": {\"line\": true, \"value\": 2, \"line_elite\": false}, \"armor\": {\"line\": true, \"value\": 2, \"line_elite\": true}}', 10, 1, 2, 2, 2, 'Строй: <img src=\"/images/icons/icon-armor.png\" class=\"img-fluid\" alt=\"armor\">2 (пока в строю с элитным существом).<br />\nСтрой: <img src=\"/images/icons/icon-ovz.png\" class=\"img-fluid\" alt=\"ovz\">2 (пока в строю с рядовым существом).'),
(49, 'Центурион', 's1_49', 'e699b', 1, 2, 5, 4, 0, 0, '', 'creature', 'uncommon', '{\"zoal\": true, \"actions\": [{\"type\": \"uchr\", \"value\": 1}, {\"key\": \"ram\", \"name\": \"Таран\", \"type\": \"self_wound_strike\", \"coins\": 1, \"target\": \"opposite\"}], \"save_coins\": true}', 10, 2, 2, 3, 4, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «таран» — получить X ран, при этом ранить на X-1 стоящее напротив существо противника.'),
(50, 'Хранитель гор', 's1_50', 'c47aa', 1, 2, 5, 5, 0, 0, '', 'creature', 'common', '{\"zoo\": true, \"ability\": {\"value\": 2, \"element\": \"swamps\"}}', 13, 1, 2, 2, 3, '+2 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по болотным.'),
(51, 'Призывающая бурю', 's1_51', 'a3c46', 1, 2, 6, 4, 0, 1, '', 'creature', 'uncommon', NULL, 7, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «мороз, мгла и ливень» — выбрать ряд половины поля боя противника; до конца хода противника сводит каждую атаку рядового существа противника к 1, пока оно стоит в выбранном ряду (1 раз за бой для каждого ряда).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1-2-2, дальность 4.'),
(52, 'Тан Ханеранга', 's1_52', 'b4bfa', 1, 2, 6, 4, 0, 1, 'Гном', 'creature', 'uncommon', '{\"armor\": {\"value\": 1}, \"damage_reduction\": [{\"line\": true, \"types\": [\"magic\", \"discharge\"], \"value\": 1}], \"line_death_next_strike_bonus\": {\"value\": 2}}', 10, 1, 2, 2, 3, 'Строй: -1 от магических ударов и разрядов.<br />\nПри гибели вашего существа со строем в ход противника — существа, которые стояли с ним в строю, получают +2 к следующему <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(53, 'Гном-басаарг', 's1_53', 'a07c5', 1, 2, 7, 5, 0, 0, 'Гном', 'creature', 'uncommon', '{\"ova\": {\"value\": 1}, \"direct\": {\"check\": true, \"closed\": true}, \"ability\": [{\"line\": true, \"value\": 1}, {\"value\": 1, \"closed\": true}], \"forced_strike\": true}', 12, 1, 2, 3, 4, 'Строй: +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.<br />\n+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> по закрытым существам.<br />\nЕсли в свой ход Гном-басаарг может атаковать простым ударом закрытое существо противника, он обязан это сделать.'),
(54, 'Искатель тайн', 's1_54', 'df35f', 1, 2, 3, 3, 1, 0, 'Линунг', 'creature', 'uncommon', '{\"actions\": [{\"type\": \"discharge\", \"range\": 3, \"value\": 1}], \"prophecy\": 1, \"prophecy_transform\": true}', 5, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1, дальность 3.<br />\nВ начале вашего хода пророчество 1; если показанная карта <img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\">, Искатель тайн может получить полет и +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца боя, при этом теряет все особенности.'),
(55, 'Борг', 's1_55', 'c2501', 1, 2, 4, 4, 1, 0, '', 'creature', 'uncommon', '{\"actions\": [{\"near\": true, \"type\": \"tap\", \"coins\": 1, \"value\": 3, \"marker\": {\"if\": \"target_closed\", \"type\": \"stun\", \"expire\": 1, \"timing\": \"owner_turn\"}}], \"save_coins\": true}', 10, 1, 2, 3, 4, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Особый удар на 3. При особом ударе по закрытому существу оно не открывается в свой следующий ход (воздействие «оглушение»).'),
(56, 'Ном', 's1_56', 'f6843', 1, 2, 4, 4, 1, 1, '', 'fly', 'rare', '{\"direct\": {\"check\": true, \"types\": [\"throw\"]}, \"on_death\": [{\"type\": \"damage\", \"value\": 3, \"filter\": \"enemy_creature_not_flying\", \"target\": \"choice\"}]}', 7, 0, 2, 3, 4, '<img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> по картам с метанием. При гибели ранить нелетающее существо противника на 3 (воздействие «штопор»).'),
(57, 'Криомант', 's1_57', 'b3541', 1, 2, 5, 4, 1, 1, 'Линунг', 'creature', 'rare', '{\"start\":{\"side\":2,\"type\":\"get_coins\",\"coins\":1},\"actions\":[{\"key\":\"ice_rain\",\"name\":\"Ледяной дождь\",\"type\":\"freeze_moves\",\"coins\":1,\"strike\":{\"weak\":3,\"medium\":2,\"strong\":1}},{\"type\":\"discharge\",\"value\":1}],\"save_coins\":true}', 8, 1, 1, 1, 2, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «ледяной дождь» — в следующий ход противника он может перемещаться только 3-2-1 существами.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.<br />\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(58, 'Молотобоец', 's1_58', 'c2511', 1, 2, 5, 4, 1, 0, '', 'creature', 'common', '{\"actions\": [{\"name\": \"Получить направку\", \"self\": true, \"type\": \"tap\", \"grant_modifier\": {\"stat\": \"direct\", \"value\": true}}], \"strike_effects\": [{\"push\": 2, \"levels\": [\"weak\", \"medium\", \"strong\"]}]}', 12, 1, 2, 3, 3, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> в свой ход может переместить атакованное существо на 1 клетку в направлении удара; если атакованный не может или не хочет быть перемещен — Молотобоец ранит его на 2 (воздействие «удар молота»).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\">.'),
(59, 'Оборотень', 's1_59', 'f7576', 1, 2, 5, 5, 1, 0, '', 'creature', 'rare', '{\"valhalla\": [{\"type\": \"heal\", \"value\": 1, \"target\": \"own_yordling\"}], \"pre_turn_start\": {\"expire\": \"end_of_turn\", \"options\": [{\"label\": \"Регенерация 2\", \"modifiers\": [{\"stat\": \"regeneration\", \"value\": 2}]}, {\"label\": \"+2 к strike, +1 к move\", \"modifiers\": [{\"stat\": \"ability_strike\", \"value\": 2}, {\"stat\": \"move\", \"value\": 1}]}]}}', 10, 1, 2, 3, 4, 'До начала вашего хода Оборотень получает либо <img src=\"/images/icons/icon-regen.png\" class=\"img-fluid\" alt=\"regen\">2, либо +2 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и +1 к <img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\"> (до конца хода противника).<br />\r\nВальхалла: излечить вашего йордлинга на 1.'),
(60, 'Аргвальд', 's1_60', 'c0c25', 1, 2, 6, 5, 1, 1, 'Йордлинг', 'creature', 'rare', '{\"actions\": [{\"key\": \"magic_strike\", \"type\": \"magic\", \"value\": 2, \"coin_bonus\": 1, \"reset_coins_after\": true}], \"save_coins\": true, \"ranged_intercept\": [\"discharge\"], \"on_discharge_self\": {\"coins\": 1}}', 12, 1, 2, 3, 3, 'Карты противника могут объявлять разряд только по Аргвальду, пока он стоит рядом с хотя бы одним существом противника (вне зависимости от дальности). При разряде по Аргвальду — он получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 2. +1 к магическому удару за каждую <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> на Аргвальде, при магическом ударе — теряет все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(61, 'Горный великан', 's1_61', 'da901', 1, 2, 6, 5, 1, 0, '', 'creature', 'common', '{\"ovz\": {\"line\": true, \"value\": 1}, \"zoo\": true}', 17, 1, 2, 3, 5, 'Строй: <img src=\"/images/icons/icon-ovz.png\" class=\"img-fluid\" alt=\"ovz\">1.'),
(62, 'Костедробитель', 's1_62', 'bf3f8', 1, 2, 6, 5, 1, 0, 'Йордлинг', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"ovz\": {\"value\": 1}, \"valhalla\": [{\"only\": [\"strike\"], \"stat\": \"ability_strike\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\", \"target\": \"own_creature\"}]}', 12, 1, 3, 5, 6, 'Вальхалла: ваше существо получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца вашего хода.'),
(63, 'Рагнар', 's1_63', 'ecf0c', 1, 2, 6, 5, 1, 1, 'Йордлинг', 'creature', 'rare', NULL, 10, 2, 2, 3, 5, 'Первая за ход способность Вальхаллы вашей карты срабатывает дважды.<br />\nВальхалла: первый за ход <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> вашего существа становится безответным.'),
(64, 'Гобрах', 's1_64', 'f4196', 1, 2, 7, 5, 1, 0, '', 'creature', 'uncommon', '{\"regeneration\": {\"value\": 3}, \"damage_reduction\": [{\"types\": [\"strike\", \"tap\", \"magic\"], \"value\": 2, \"attacker_diagonal\": true}]}', 10, 2, 4, 4, 5, '-2 от ударов по диагонали.'),
(65, 'Ледовый страж', 's1_65', 'f0564', 1, 2, 7, 4, 1, 1, '', 'creature', 'ultrarare', '{\"actions\": [{\"key\": \"heal_self\", \"name\": \"Излечение\", \"self\": true, \"type\": \"heal\", \"value\": 3}], \"instants\": [{\"key\": \"okovy\", \"name\": \"Оковы льда\", \"effect\": {\"type\": \"close_target\", \"condition\": \"target_not_moved\"}, \"target\": \"enemy\", \"trigger\": \"turn\"}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «оковы льда» — закрыть существо, которое не передвигалось в этот ход.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечиться на 3.'),
(66, 'Повелитель молний', 's1_66', 'bc06b', 1, 2, 7, 5, 1, 1, 'Линунг', 'creature', 'rare', '{\"zom\": true, \"coins\": {\"discharge\": {\"spend\": 1, \"value\": 3}, \"max_value\": 3}, \"actions\": [{\"type\": \"discharge\", \"value\": 2}], \"save_coins\": true}', 9, 1, 2, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 2. +3 к разряду за каджую <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> на Повелителе молний. При разряде — теряет одну <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. Не может иметь более 3<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. Игнорирует особенности, обязывающие выбирать целью разряда какую-либо карту.'),
(67, 'Гномий король', 's1_67', 'e8dd5', 1, 2, 8, 5, 1, 1, 'Гном', 'creature', 'ultrarare', NULL, 12, 1, 3, 4, 6, 'Строй: -1 от немагических атак. Существа в строю с Гномьим королем получают +1 к удару.<br />\nПри дальней атаке по существу в вашем втором или третьем ряду может перенаправить эту атаку на существо, стоящее в строю с Гномьим королем (1 раз за ход для каждого атакованного существа).'),
(68, 'Владыка небес', 's1_68', 'c1c81', 1, 2, 9, 5, 1, 1, 'Дракон', 'creature', 'ultrarare', '{\"zoz\": true, \"ignore\": [\"zoal\", \"zoa\"], \"ability\": {\"only\": [\"strike\"], \"value\": 3, \"target_marker\": \"prey\"}, \"actions\": [{\"key\": \"become_fly\", \"name\": \"Получить полёт\", \"self\": true, \"type\": \"become_fly\"}], \"unanswer\": {\"check\": true, \"target_marker\": \"prey\"}, \"on_hit_marker\": {\"type\": \"prey\"}}', 14, 1, 2, 3, 4, 'Игнорирует <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.<br />\r\nПри ударе по существу – оно получает маркер «добычи». +3 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и безответный удар по существам с маркером «добычи».<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить полет.'),
(69, 'Атекар', 's1_69', 'e0a28', 1, 3, 3, 4, 0, 0, 'Дитя Кронга', 'creature', 'common', '{\"ability\": {\"only\": [\"throw\"], \"value\": 1, \"condition\": \"ally_opposite_no_wounds\"}, \"actions\": [{\"type\": \"throw\", \"range\": 3, \"strike\": {\"weak\": 0, \"medium\": 1, \"strong\": 2}}], \"regeneration\": {\"value\": 1}}', 6, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «шишки» на 0-1-2, дальность 3. +1 к метанию, если напротив Атекара стоит ваше существо без ран.'),
(70, 'Дракс', 's1_70', 'a02e7', 1, 3, 3, 4, 0, 1, 'Дракон', 'fly', 'common', '{\"direct\": true, \"ability\": {\"types\": [\"magic\", \"cast\", \"discharge\"], \"value\": 1}}', 5, 0, 1, 1, 2, '+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по картам, обладающим разрядом, магическим ударом или заклинанием.'),
(71, 'Леший', 's1_71', 'e07e1', 1, 3, 3, 4, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"self\": true, \"type\": \"heal\", \"value\": \"full\"}]}', 7, 1, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Полностью излечиться.'),
(72, 'Фея леса', 's1_72', 'e764f', 1, 3, 3, 3, 0, 1, '', 'fly', 'common', '{\"actions\": [{\"key\": \"pollen\", \"name\": \"Волшебная пыльца\", \"type\": \"heal\", \"value\": 1, \"filter\": \"own_forest\", \"max_targets\": 3}]}', 5, 0, 1, 1, 1, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «волшебная пыльца» — излечить до трех ваших лесных существ на 1.'),
(73, 'Друид', 's1_73', 'bd97c', 1, 3, 4, 4, 0, 0, 'Страж леса', 'creature', 'common', '{\"zoo\": true, \"actions\": [{\"own\": true, \"type\": \"heal\", \"value\": 2, \"heal_poison\": true}]}', 7, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «дыхание леса» — излечить существо на 2 и снять с него отравление.'),
(74, 'Корпит', 's1_74', 'c7564', 1, 3, 4, 4, 0, 0, '', 'fly', 'common', '{\"direct\": true, \"deadeat\": true}', 6, 0, 1, 2, 2, 'Трупоедство.'),
(75, 'Лесной разбойник', 's1_75', 'dac00', 1, 3, 4, 2, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"key\": \"steal_weapon\", \"name\": \"Украсть оружие\", \"type\": \"steal_strike\", \"coins\": 1, \"once_per_battle\": true}], \"save_coins\": true, \"can_move_diagonal\": true}', 8, 1, 1, 2, 3, 'Может двигаться по диагонали.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «украсть оружие» (1 раз за бой) — стоящее рядом существо противника получает -1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, при этом Лесной разбойник получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(76, 'Оури', 's1_76', 'fd801', 1, 3, 4, 4, 0, 0, 'Дитя Кронга', 'creature', 'common', '{\"zor\": true, \"actions\": [{\"own\": true, \"type\": \"heal\", \"value\": 1}, {\"key\": \"shot_cond\", \"name\": \"Выстрел\", \"type\": \"shot\", \"range\": 3, \"value\": 1, \"no_close\": true, \"condition\": {\"min\": 7, \"type\": \"ally_price_near\"}}]}', 8, 2, 1, 1, 2, 'При перемещении на клетку, рядом с которой стоит ваше существо стоимостью 7 или более, может объявить выстрел на 1, дальность 3.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечить существо на 1.'),
(77, 'Паук-пересмешник', 's1_77', 'b0109', 1, 3, 4, 4, 0, 0, '', 'creature', 'common', '{\"air_intercept\": true}', 7, 1, 1, 2, 2, 'Летающие существа противника могут объявлять атаку только по Пауку-пересмешнику.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «бросок сети», дальность 2 — нелетающее существо противника получает «сеть» на свой следующий ход — не может передвигаться и действовать. Если существо с «сетью» атаковано, то эта атака блокируется, а «сеть» исчезает.'),
(78, 'Эриала', 's1_78', 'b96cd', 1, 3, 4, 4, 0, 0, 'Эльф', 'creature', 'uncommon', '{\"ability\": {\"value\": 1, \"position\": \"row_mirror\"}, \"actions\": [{\"type\": \"shot\", \"value\": 1, \"near_shot\": true}]}', 8, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1. Может стрелять по стоящим рядом картам.<br />\n+1 к выстрелу по картам в 3-м ряду противника, если стоит в вашем 3-м ряду.<br />\n+1 к выстрелу по картам во 2-м ряду противника, если стоит в вашем 2-м ряду.<br />\n+1 к выстрелу по картам в 1-м ряду противника, если стоит в вашем 1-м ряду.'),
(79, 'Бегущая по кронам', 's1_79', 'a82de', 1, 3, 5, 5, 0, 0, 'Эльф', 'creature', 'uncommon', '{\"ability\": {\"check\": true, \"types\": [\"shot\"], \"value\": 1}, \"actions\": [{\"type\": \"shot\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}}], \"turn_start\": [{\"type\": \"position_modifier\", \"scope\": \"any\", \"position\": \"near\", \"modifiers\": [{\"stat\": \"shot_bonus\", \"value\": 1}]}, {\"type\": \"position_modifier\", \"scope\": \"any\", \"position\": \"far\", \"modifiers\": [{\"stat\": \"direct\", \"value\": true}]}]}', 9, 2, 2, 3, 4, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1-2-2.<br />\nВ начале хода, если стоит в вашем первом ряду, получает +1 к выстрелам до конца хода.<br />\nВ начале хода, если стоит в вашем третьем ряду, получает <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> до конца хода.'),
(80, 'Бьерн', 's1_80', 'df610', 1, 3, 5, 4, 0, 0, 'Страж леса', 'creature', 'common', '{\"ovz\": {\"value\": 1}, \"zom\": true, \"on_become_defender\": [{\"type\": \"heal_target\", \"value\": 2}]}', 10, 1, 2, 2, 3, 'Когда Бьерн становится защитником — излечить на 2 существо, которому он выступает защитником.'),
(81, 'Вожак сатиров', 's1_81', 'd24e4', 1, 3, 5, 5, 0, 0, 'Дитя Кронга', 'creature', 'uncommon', NULL, 12, 1, 2, 3, 4, '-1 от атак летающих.<br />\nПока не имеет ран, получает «Если должен излечиться на X — вместо этого может ранить стоящее рядом существо на X (до 3 раз за ход)».'),
(82, 'Клаэр', 's1_82', 'c0c3f', 1, 3, 5, 4, 0, 0, 'Дитя Кронга', 'creature', 'common', '{\"zov\": true, \"on_become_defender\": [{\"stat\": \"ova\", \"value\": 1}, {\"stat\": \"ability_strike\", \"value\": 2}]}', 11, 2, 1, 2, 4, 'Когда Клаэр становится защитником, она получает +2 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 до конца вашего следующего хода.'),
(83, 'Серк', 's1_83', 'ab62c', 1, 3, 5, 4, 0, 0, 'Дитя Кронга', 'creature', 'common', '{\"zot\": true, \"damage_reduction\": [{\"value\": 1, \"attacker_move_min\": 2}], \"on_heal_instead_open\": {\"once_per_turn\": true}}', 9, 2, 2, 2, 3, 'Пока не имеет ран, получает «Если должен излечиться — вместо этого может открыться (1 раз за ход)».<br />\n-1 от атак существ с <img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\">2 или больше.');
INSERT INTO `cards` (`ind`, `name`, `ukid`, `code`, `release_id`, `element_id`, `price`, `power`, `elite`, `single`, `class`, `type`, `rarity`, `prop`, `health`, `move`, `strike_weak`, `strike_medium`, `strike_strong`, `descr`) VALUES
(84, 'Камнедрев', 's1_84', 'f03c2', 1, 3, 6, 4, 0, 0, '', 'creature', 'common', '{\"coins\": {\"max_value\": 10}, \"turn_start\": [{\"type\": \"get_coins\", \"coins\": 1}], \"regeneration\": {\"value\": 1}, \"coin_strike_bonus\": true, \"lose_coins_on_move\": true}', 12, 1, 2, 3, 4, 'Неповоротливость.<br />\nВ конце вашего хода может получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">, если не перемещался в этот ход.<br />\n+X к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, где X — количество <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> на Камнедреве.<br />\nПри движении Камнедрев теряет все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(85, 'Леккен', 's1_85', 'aa0d9', 1, 3, 6, 5, 0, 0, 'Страж леса', 'creature', 'uncommon', '{\"ovz\": {\"value\": 1}, \"zor\": true, \"defender\": {\"all\": true}}', 10, 1, 2, 2, 3, 'Выступая защитником, не закрывается. Может выступать защитником любое число раз за ход.'),
(86, 'Мира', 's1_86', 'dc1c0', 1, 3, 6, 2, 0, 1, 'Эльф', 'creature', 'rare', '{\"actions\": [{\"type\": \"shot\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 3}, \"close_on_ranged_hits\": 2}], \"damage_reduction\": [{\"types\": [\"shot\", \"throw\", \"discharge\", \"uchr\"], \"value\": 1, \"require_no_wounds\": true}]}', 9, 1, 1, 2, 2, '-1 от дальних атак, пока не имеет ран.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1-2-3, при этом закройте атакованное существо, если оно получало раны от двух или более других выстрелов или метаний в этот ход.'),
(87, 'Фагор', 's1_87', 'abcd8', 1, 3, 7, 5, 0, 0, 'Страж леса', 'creature', 'uncommon', '{\"actions\": [{\"key\": \"fagor_magic\", \"name\": \"Магический удар\", \"type\": \"magic\", \"coins\": 1, \"value\": \"adjacent_ally_weak_sum\"}], \"save_coins\": true}', 12, 1, 3, 3, 5, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на X, где X — сумма слабых <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> ваших существ справа и слева от Фагора.'),
(88, 'Резчик идолов', 's1_88', '1c15a', 1, 3, 4, 4, 1, 1, 'Эльф', 'creature', 'common', '{\"ranged_intercept\": true}', 10, 1, 1, 2, 2, 'Карты противника могут объявлять выстрел и метание только по Резчику идолов, пока он стоит рядом с хотя бы одним существом противника (вне зависимости от дальности).'),
(89, 'Грызь', 's1_89', 'b18b3', 1, 3, 5, 5, 1, 0, '', 'creature', 'uncommon', '{\"zom\": true, \"zov\": true, \"actions\": [{\"key\": \"jump_card\", \"type\": \"jump\", \"range\": 4}, {\"type\": \"uchr\", \"value\": 1}, {\"key\": \"empower\", \"name\": \"Свирепость\", \"self\": true, \"type\": \"grant_modifier\", \"grant_modifier\": [{\"stat\": \"direct\", \"value\": 1, \"expire\": \"permanent\"}, {\"stat\": \"zoal\", \"value\": 1, \"expire\": \"permanent\"}]}]}', 6, 1, 4, 4, 5, 'Прыжок, дальность 4.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> и <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.'),
(90, 'Дверг', 's1_90', 'eda90', 1, 3, 5, 4, 1, 0, '', 'creature', 'ultrarare', NULL, 7, 1, 1, 2, 3, '[Эррата 2023.04.08]<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «дух мухомора» — выбранное существо до конца хода получает: «<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар той же величины, что и <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> этого существа и +1 к этому удару (1 раз за ход)».<br />\r\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с 3 дополнительными жизнями.'),
(91, 'Дикий целитель', 's1_91', 'ea263', 1, 3, 5, 4, 1, 0, 'Дитя Кронга', 'creature', 'uncommon', NULL, 10, 2, 2, 2, 4, 'Получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">, пока рядом с Диким целителем стоят хотя бы три ваших существа без ран.<br />\nПри перемещении может излечить соседнее существо на 1.'),
(92, 'Кобольд', 's1_92', 'a18a2', 1, 3, 5, 4, 1, 0, '', 'creature', 'common', '{\"zov\": true, \"actions\": [{\"type\": \"uchr\", \"value\": 1}], \"on_successful_hit\": {\"type\": \"optional_heal\", \"value_from\": \"opposite_creature_strike_medium\"}}', 11, 1, 2, 3, 4, '[Эррата 2023.04.08]<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\r\nПри ударе Кобольд может излечиться на X, где X — величина <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> существа напротив.'),
(93, 'Очи Кронга', 's1_93', 'c9a66', 1, 3, 5, 4, 1, 1, 'Страж леса', 'fly', 'ultrarare', NULL, 8, 0, 2, 2, 3, 'Когда другие лесные существа в вашем отряде выполняют удар, выстрел и излечение подряд в любой последовательности (перемещение не прерывает цепочку) — открыть Очи Кронга (до 2 раз за ход).'),
(94, 'Король-жрец', 's1_94', 'd68e7', 1, 3, 6, 3, 1, 1, '', 'creature', 'rare', NULL, 10, 2, 1, 2, 3, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «потеря памяти» — существо теряет все оссобенности до тех пор, пока Король-жрец не покинет поле боя (1 раз за бой).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечить существо на 2.'),
(95, 'Ловец душ', 's1_95', 'a6afd', 1, 3, 6, 4, 1, 1, 'Эльф', 'creature', 'uncommon', '{\"zoal\":true,\"coins\":{\"max_value\":5},\"actions\":[{\"key\":\"particle\",\"name\":\"Частица души\",\"type\":\"particle\",\"value\":1,\"max_targets\":2},{\"key\":\"life_gift\",\"name\":\"Предсмертный дар\",\"type\":\"life_gift\",\"min_x\":1}],\"save_coins\":true,\"on_any_death\":{\"side\":\"any\",\"cause\":\"any\",\"value\":1,\"effect\":\"get_coin\"}}', 8, 1, 1, 2, 3, 'При гибели существа получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. Не может иметь более 5<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «частица души» — ранить двух или менее существ без ран на 1.<br />\nX<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «предсметный дар» — ранить существо противника на X, при этом излечить вашше существо на X.'),
(96, 'Тергала', 's1_96', 'c0220', 1, 3, 6, 4, 1, 1, 'Эльф', 'creature', 'rare', '{\"actions\": [{\"key\": \"flower_runes\", \"name\": \"Цветущие руны\", \"type\": \"row_spell\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}}, {\"type\": \"discharge\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}}]}', 8, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «цветущие руны» — выберите ряд, в начале вашего следующего хода ранить X существ противника на 1-2-2, где X — количество ваших существ без ран в выбранном ряду.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1-2-2.'),
(97, 'Эльфийский воин', 's1_97', 'd4ab2', 1, 3, 6, 4, 1, 0, 'Эльф', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"auto\": [{\"type\": \"shot\", \"range\": 0, \"value\": 2, \"attack\": true}], \"damage_reduction\": [{\"types\": [\"strike\", \"tap\", \"uchr\", \"shot\", \"throw\"], \"value\": 1, \"element\": \"plains\"}]}', 10, 1, 2, 3, 4, '-1 от атак степных существ.<br />\nПри ударе или при промахе в нападении — выстрел на 2.'),
(98, 'Етун', 's1_98', 'd5cc0', 1, 3, 7, 5, 1, 0, '', 'creature', 'rare', NULL, 14, 2, 3, 4, 5, 'Игнорирует особенности атакованного существа.'),
(99, 'Серый альв', 's1_99', 'c1be2', 1, 3, 7, 4, 1, 0, '', 'creature', 'rare', NULL, 9, 1, 2, 3, 4, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 2-3-3.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">: Выстрел «огненной стрелой» на 5 (игнорирует особенности атакованного существа).'),
(100, 'Хобгоблин', 's1_100', 'd9bc5', 1, 3, 8, 5, 1, 0, '', 'creature', 'common', '{\"zoo\": true, \"direct\": true, \"damage_reduction\": [{\"types\": [\"strike\", \"tap\", \"uchr\", \"shot\", \"throw\"], \"value\": 2, \"max_price\": 3}]}', 18, 1, 3, 4, 5, '-2 от немагических атак существ стоимостью 3 или менее.'),
(101, 'Циклоп', 's1_101', 'afe0c', 1, 3, 8, 5, 1, 0, '', 'creature', 'rare', '{\"zom\": true, \"zoo\": true, \"direct\": true, \"strike\": {\"opposite\": true}, \"actions\": [{\"type\": \"magic\", \"value\": 2}], \"regeneration\": {\"value\": 1}}', 14, 2, 4, 5, 6, 'Может объявлять <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> только по карте, стоящей напротив.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 2.'),
(102, 'Келе', 's1_102', 'c50c1', 1, 3, 9, 5, 1, 0, 'Дитя Кронга', 'creature', 'ultrarare', NULL, 16, 1, 3, 4, 5, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 3-4-5.<br />\nПри <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> может излечиться на 2, если после этого у Келе нет ран — не закрывается после этой атаки.'),
(103, 'Ижор', 's1_103', 'ea1c3', 1, 4, 3, 3, 0, 0, 'Архаалит', 'creature', 'common', '{\"ability\": [{\"only\": [\"shot\"], \"value\": 1, \"position\": \"enemy_second_row\"}], \"actions\": [{\"key\": \"shot1\", \"type\": \"shot\", \"range\": 4, \"value\": 1, \"strike_effects\": [{\"levels\": [\"strong\"], \"poison\": 1}]}]}', 6, 1, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1, дальность 4. При сильной атаке — атакованный получает отравление на 1.<br />\n+1 к броску кубика, когда атакует карты во втором ряду противника.'),
(104, 'Махинатор', 's1_104', 'd9c77', 1, 4, 3, 5, 0, 1, 'Архаалит', 'creature', 'common', '{\"actions\": [{\"key\": \"trick\", \"name\": \"Уловка\", \"type\": \"steal_coin\", \"value\": 1, \"once_per_battle\": true}, {\"key\": \"discharge1\", \"type\": \"discharge\", \"range\": 3, \"value\": 1}], \"prophecy_reorder\": true}', 6, 1, 1, 2, 2, 'При пророчестве ваших карт можете вернуть показанные карты на верх колоды в любом порядке (1 раз за ход).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «уловка» — существо теряет <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> (1 раз за бой).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1, дальность 3.'),
(105, 'Отряд карателей', 's1_105', 'c6482', 1, 4, 3, 4, 0, 0, 'Архаалит', 'creature', 'common', '{\"prophecy_summon\": true}', 5, 1, 1, 2, 3, 'Когда вы показываете Отряд карателей при пророчестве — может вызвать его на незанятую клетку в закрытом виде, при этом существо, стоящее рядом с вызванным, получает отравление на 1.'),
(106, 'Римаанды', 's1_106', 'd4029', 1, 4, 3, 4, 0, 0, 'Архаалит', 'fly', 'common', '{\"unanswer\": {\"check\": true, \"condition\": \"isolated_horizontally\"}}', 6, 0, 1, 2, 3, 'Может объявлять безответный удар по существу противника, если и справа и слева от него нет других его существ.'),
(107, 'Болотник', 's1_107', 'bec9e', 1, 4, 4, 4, 0, 0, '', 'creature', 'common', '{\"start\": {\"side\": 2, \"type\": \"get_coins\", \"coins\": 1}, \"actions\": [{\"type\": \"jump\", \"range\": 4}, {\"name\": \"Ядовитый взрыв\", \"type\": \"impact\", \"coins\": 1, \"value\": 1, \"filter\": \"enemy\", \"poison\": 1, \"target\": \"all_near\", \"self_destroy\": true}], \"save_coins\": true}', 5, 1, 1, 1, 1, 'Прыжок, дальность 4.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Уничтожить Болотника, при этом ранить всех стоящих рядом существ противника на 1, они получают отравление на 1 (воздействие «ядовитый взрыв»).<br />\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(108, 'Дети топи', 's1_108', 'eed44', 1, 4, 4, 5, 0, 0, 'Архаалит', 'creature', 'uncommon', NULL, 9, 1, 1, 2, 3, 'При первом за ход ударе существа противника по Детям топи — заблокировать этот удар, при этом прыжок, дальность 2.<br />\nПосле прыжка Детей топи — существо противника по его выбору рядом с освободившейся клеткой перемещается на эту клетку.'),
(109, 'Осклизг', 's1_109', 'bf505', 1, 4, 4, 4, 0, 0, 'Тролль', 'creature', 'common', '{\"zom\": true, \"start\": {\"side\": 2, \"type\": \"get_coins\", \"coins\": 1}, \"actions\": [{\"type\": \"uchr\", \"value\": 1}, {\"key\": \"elixirs\", \"kind\": \"osklizg\", \"name\": \"Эликсиры Ракштольна\", \"type\": \"wound_transfer\", \"coins\": 1, \"on_finish\": \"main_phase\", \"donor_near\": true, \"donor_filter\": \"wounded\", \"max_transfer\": 4, \"donor_element\": \"swamps\", \"target_filter\": \"source\"}], \"save_coins\": true, \"regeneration\": {\"value\": 2}}', 8, 1, 1, 2, 3, '<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «эликсиры Ракштольна» — перераспределить 4 (или менее) раны со стоящего рядом болотного существа на себя.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\r\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(110, 'Рэккен', 's1_110', 'd7eae', 1, 4, 4, 4, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"key\": \"rekken\", \"kind\": \"rekken\", \"name\": \"Рэккендум\", \"type\": \"wound_transfer\", \"on_finish\": \"main_phase\", \"donor_filter\": \"wounded\", \"max_transfer\": 2, \"donor_element\": \"swamps\", \"target_filter\": \"source\"}, {\"key\": \"knife\", \"name\": \"Метание ритуального ножа\", \"type\": \"throw\", \"range\": 4, \"value\": \"self_wounds\", \"max_value\": 4}]}', 7, 1, 1, 1, 1, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «рэккендум» — перераспределить 2 (или менее) раны с другого болотного существа на себя.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «ритуального ножа» на X, дальность 4, где X — число ран на Рэккене (максимум 4).'),
(111, 'Тови', 's1_111', 'a30fc', 1, 4, 4, 5, 0, 0, 'Речная дева', 'creature', 'common', '{\"actions\": [{\"type\": \"throw\", \"strike\": {\"weak\": 1, \"medium\": 1, \"strong\": 1}}], \"force_opponent_directional_move\": {\"distance\": 1, \"fallback\": {\"modifier\": {\"stat\": \"next_action_bonus\", \"types\": [\"throw\"], \"value\": 2, \"expire\": \"end_of_turn\", \"consume\": true}}}}', 7, 1, 1, 2, 2, 'При движении Тови на соседнюю клетку — противник обязан переместить любое свое существо в том же направлении (относительно Тови); если он не может или не хочет этого делать — Тови получает +2 к следующему метанию (до конца вашего хода).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «жабы» на 1.'),
(112, 'Хедд', 's1_112', 'a80b0', 1, 4, 4, 4, 0, 0, 'Архаалит', 'creature', 'common', '{\"regeneration\": {\"value\": 1}, \"strike_effects\": [{\"levels\": [\"medium\", \"strong\"], \"poison\": 1}]}', 8, 1, 2, 2, 3, 'При среднем или сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — атакованный получает отравление на 1.'),
(113, 'Гаррид-лучник', 's1_113', 'bd5fc', 1, 4, 5, 5, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"type\": \"shot\", \"range\": 4, \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 3}}]}', 9, 2, 2, 3, 4, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1-2-3, дальность 4.'),
(114, 'Грезы Архааля', 's1_114', 'db80f', 1, 4, 5, 4, 0, 0, 'Архаалит', 'creature', 'uncommon', '{\"actions\": [{\"key\": \"grezy\", \"name\": \"Грезы Архааля\", \"type\": \"grezy_prophecy\", \"count\": 1}]}', 8, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Пророчество 1; существо противника стоимостью X получает отравление на 1, ваше существо стоимостью X получает -1 от немагических атак до конца хода противника (где X — стоимость показанной карты без учета элитности).'),
(115, 'Кровяница', 's1_115', 'baa06', 1, 4, 5, 5, 0, 0, 'Речная дева', 'creature', 'uncommon', NULL, 11, 2, 2, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Добивание на X+1, где X – число отравленных существ рядом с целью добивания.'),
(116, 'Василиск', 's1_116', 'e128e', 1, 4, 6, 5, 0, 0, '', 'creature', 'common', '{\"direct\": true, \"strike_effects\": [{\"levels\": [\"weak\", \"medium\", \"strong\"], \"rooted\": true}]}', 12, 1, 2, 3, 4, 'При ударе — атакованное существо не может передвигаться с той клетки, где оно находилось на момент этого удара, пока Василиск не переместится, или не покинет поле боя (воздействие «взгляд Василиска»).'),
(117, 'Вайл', 's1_117', 'e370c', 1, 4, 6, 2, 0, 0, '', 'creature', 'common', NULL, 14, 1, 1, 1, 4, ''),
(118, 'Шаман-душегрыз', 's1_118', 'b347a', 1, 4, 6, 4, 0, 1, 'Тролль', 'creature', 'rare', NULL, 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «гипноз» — открытое существо противника наносит по стоящей рядом карте <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и закрывается.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-zoal.png\" class=\"img-fluid\" alt=\"zoal\">.<br />\n<img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(119, 'Бул\'Багур', 's1_119', 'a40c7', 1, 4, 7, 5, 0, 1, 'Тролль', 'creature', 'rare', '{\"ova\": {\"value\": 1}, \"opponent_turn_start\": [{\"stat\": \"ova\", \"type\": \"modifier\", \"value\": 1, \"expire\": \"end_of_turn\"}]}', 10, 1, 2, 3, 3, 'В начале хода противника выберите до 3 клеток подряд на одной прямой (в том числе по диагонали) от Бул\'Багура — до конца вашего следующего хода карты получают на 1 рану больше от дальних атак, отравления и удара Бул\'Багура, пока находятся на этих клетках (воздействие «свет фонаря»).'),
(120, 'Гоблин', 's1_120', 'd2267', 1, 4, 7, 4, 0, 0, '', 'creature', 'common', '{\"direct\": true, \"strike_effects\": [{\"close\": true}], \"damage_reduction\": [{\"types\": [\"strike\"], \"value\": 2}]}', 10, 1, 2, 2, 3, '-2 от <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.<br />\nПри ударе или промахе в нападении — закрыть атакованное существо (воздействие «оцепенение»).'),
(121, 'Слизь', 's1_121', 'c255b', 1, 4, 7, 3, 0, 0, '', 'creature', 'common', '{\"auto\": [{\"name\": \"Плевок слизью\", \"type\": \"shot\", \"range\": 3, \"value\": 1, \"trigger\": \"strike_hit\"}], \"answer\": {\"types\": [\"strike\", \"tap\", \"magic\"], \"value\": 1}, \"actions\": [{\"near\": true, \"type\": \"tap\", \"coins\": 1, \"value\": 3, \"poison\": 1}], \"save_coins\": true, \"regeneration\": {\"value\": 1}}', 10, 1, 3, 3, 4, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — выстрел «плевок слизью» на 1, дальность 3.<br />\nПри ближнем ударе по Слизи — ранить атаковавшего на 1.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Особый удар на 3; при этом атакованное существо получает отравленме на 1.'),
(122, 'Дочь перламутра', 's1_122', 'a64b9', 1, 4, 4, 4, 1, 1, 'Речная дева', 'creature', 'uncommon', '{\"ovz\": true, \"prophecy_block\": {\"chance\": \"odd\", \"once_per_turn\": true}}', 9, 1, 1, 2, 3, 'Если Дочь перламутра атакована немагической атакой – пророчество 1; блокировать атаку, если показанная карта нечетной стоимости (1 раз за ход).'),
(123, 'Ноками', 's1_123', '1ad1c', 1, 4, 4, 5, 1, 1, 'Речная дева', 'creature', 'rare', '{\"zov\":true,\"actions\":[{\"cap\":2,\"key\":\"boiling_poison\",\"name\":\"Вскипающий яд\",\"type\":\"poison_boost\",\"value\":1}],\"on_poison_damage\":{\"value\":1,\"once_per_turn\":true}}', 7, 1, 1, 2, 2, 'Когда существо противника получает раны от отравления, может ранить стоящее рядом с ним существо на 1 (1 раз за ход).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «вскипающий яд» — выбранное существо с отравлением получает +1 к отравлению (максимум до 2).'),
(124, 'Сеятель хвори', 's1_124', 'd6266', 1, 4, 4, 5, 1, 1, 'Архаалит', 'creature', 'uncommon', '{\"actions\": [{\"type\": \"discharge\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}, \"strike_effects\": [{\"levels\": [\"medium\", \"strong\"], \"poison\": 1}]}], \"on_any_death\": {\"cause\": \"poison\", \"filter\": \"any\", \"once_per_turn\": true}}', 7, 1, 1, 2, 2, 'При гибели существа противника от отравления — может отравить стоящее рядом с погибшим существо на X, где X — величина отравления умершего существа (1 раз за ход).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1-2-2, при среднем или сильном разряде — атакованный получает отравление на 1.'),
(125, 'Троллок', 's1_125', 'c2016', 1, 4, 4, 5, 1, 0, 'Тролль', 'creature', 'uncommon', '{\"ability\": {\"types\": [\"shot\", \"throw\", \"discharge\"], \"value\": 1}, \"actions\": [{\"type\": \"throw\", \"strike\": {\"weak\": 1, \"medium\": 2, \"strong\": 2}}]}', 8, 1, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание на 1-2-2.<br />\n+1 к метанию по картам, обладающим выстрелом, метанием или разрядом.'),
(126, 'Вилохвост', 's1_126', 'd3e9c', 1, 4, 5, 4, 1, 1, 'Дракон', 'fly', 'uncommon', '{\"ova\": {\"value\": 1}, \"zoo\": true, \"direct\": {\"check\": true, \"element\": \"forests\"}, \"ability\": {\"value\": 1, \"defender\": true}}', 8, 0, 2, 2, 3, '+1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по защитникам.<br />\r\n<img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\"> по лесным существам.'),
(127, 'Исхарская ненасыть', 's1_127', 'ca16d', 1, 4, 5, 4, 1, 0, '', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"zor\": true, \"prophecy_charge\": {\"cap\": 3}}', 11, 2, 1, 2, 3, 'При пророчестве вашей карты — получает +X к следующему <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, где X — количество показанных карт (максимум +3).'),
(128, 'Тролль', 's1_128', 'ffd6f', 1, 4, 5, 4, 1, 0, 'Тролль', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"regeneration\": {\"value\": 2}}', 10, 1, 2, 4, 5, ''),
(129, 'Ундина', 's1_129', 'f8a6c', 1, 4, 5, 5, 1, 1, 'Речная дева', 'creature', 'ultrarare', '{\"zoo\": true, \"zor\": true, \"zot\": true, \"actions\": [{\"key\": \"aura\", \"name\": \"Сладострастная аура\", \"type\": \"poison_target\", \"value\": 1}, {\"key\": \"power\", \"name\": \"Власть Ундины\", \"type\": \"damage_poisoned\", \"value\": 1, \"filter\": \"enemy\"}]}', 8, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «сладострастная аура» — существо получает отравление на 1.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «власть Ундины» — ранить всех отравленных существ противника на 1.'),
(130, 'Королева топи', 's1_130', 'd18c6', 1, 4, 6, 4, 1, 1, 'Архаалит', 'creature', 'ultrarare', '{\"ova\": {\"value\": 1}}', 9, 1, 1, 2, 3, 'В конце хода противника вызвать болотное существо стоимостью 5 или менее на клетку, рядом с которой стоит 8 или более ваших существ.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Пророчество 1; если карта с таким же именем есть в одном из отрядов — ранить выбранное существо на 2, иначе ранить его на 1.'),
(131, 'Медуза Горгона', 's1_131', 'f7ee5', 1, 4, 6, 5, 1, 0, '', 'creature', 'common', '{\"direct\": true, \"deadeat\": true, \"vampire\": true, \"strike_effects\": [{\"levels\": [\"strong\"], \"marker\": {\"type\": \"stun\", \"expire\": 1, \"timing\": \"owner_turn\"}}], \"hp_max_override\": 10}', 10, 2, 2, 3, 4, 'Вампиризм. Максимум 10 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">.<br />\nТрупоедство.<br />\nПри сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — атакованный закрывается и не открывается в свой следующий ход (воздействие «взгляд Медузы»).'),
(132, 'Двухголовый тролль', 's1_132', 'db5cd', 1, 4, 7, 4, 1, 0, 'Тролль', 'creature', 'rare', '{\"zoz\": true, \"regeneration\": {\"value\": 1}, \"strike_prophecy\": {\"count\": 2, \"all_elite\": {\"damage\": 2}, \"all_ordinary\": {\"poison\": 2}}}', 13, 1, 3, 3, 4, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — пророчество 2; если обе карты <img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\"> — ранить атакованного на 2, если обе карты <img src=\"/images/icons/icon-ordinary.png\" class=\"img-fluid\" alt=\"ordinary\"> — атакованный получает отравление на 2.'),
(133, 'Морок', 's1_133', 'e175a', 1, 4, 7, 5, 1, 0, '', 'creature', 'uncommon', NULL, 13, 1, 2, 2, 3, '-1 от выстрелов и метаний.<br />\n-1 от <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, пока Морок выступает защитником.<br />\n<img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по закрытому Мороку сводятся к 1. <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по картам слева и справа от Морока сводится к слабому.'),
(134, 'Уриил', 's1_134', 'e10e6', 1, 4, 7, 4, 1, 0, '', 'creature', 'rare', '{\"answer\": {\"types\": [\"strike\"], \"value\": 0, \"marker\": {\"type\": \"stun\", \"expire\": 1, \"timing\": \"owner_turn\", \"skip_first_tick\": true}}, \"regeneration\": {\"value\": 1}}', 12, 1, 3, 3, 4, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по Уриилу атаковавший не открывается в начале своего следующего хода (воздействие «мерзкая аура»).'),
(135, 'Древний огр', 's1_135', 'affc3', 1, 4, 8, 5, 1, 0, '', 'creature', 'rare', '{\"ova\": {\"value\": 1}, \"zoo\": true, \"on_hit_gain\": [{\"stat\": \"zoa\", \"value\": 1, \"expire\": \"end_of_turn\"}], \"regeneration\": {\"value\": 1}, \"damage_reduction\": [{\"types\": [\"shot\", \"throw\"], \"value\": 1}]}', 14, 1, 3, 4, 5, '-1 от выстрелов и метаний.<br />\nПри ударе по Древнему огру — он получает защиту от ударов до конца хода.'),
(136, 'Гидра', 's1_136', 'c76f5', 1, 4, 9, 5, 1, 1, '', 'creature', 'ultrarare', NULL, 13, 1, 2, 3, 3, 'Безответный удар. Может нападать <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> на всех стоящих рядом существ противника, только подряд, после последнего нападения закрывается.<br />\r\nСила <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> Гидры не может быть снижена.'),
(137, 'Вестник мора', 's1_137', 'd580c', 1, 5, 3, 4, 0, 0, 'Нежить', 'creature', 'common', '{\"ovz\": {\"value\": 1}, \"incarnation\": {\"type\": \"fly\", \"turns\": 3}}', 5, 1, 1, 2, 2, 'Инкарнация 3.<br />\nПри инкарнации — получить полет.'),
(138, 'Огненный имп', 's1_138', 'a3b1f', 1, 5, 3, 4, 0, 0, 'Демон', 'creature', 'common', '{\"actions\": [{\"key\": \"lava\", \"name\": \"Лава\", \"type\": \"throw\", \"range\": 4, \"value\": 1}], \"on_teleport_adjacent_bonus\": {\"types\": [\"throw\"], \"value\": 1}}', 5, 1, 1, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «лавы» на 1, дальность 4.<br />\nПри телепортации вашего существа на половину поля боя противника с соседней с Огненным импом клетки — Огненный имп получает +1 к следующему метанию (максимум +1) до конца вашего хода.'),
(139, 'Вампир', 's1_139', 'f908d', 1, 5, 4, 5, 0, 0, 'Слуа', 'creature', 'common', '{\"vampire\": true, \"unanswer\": true, \"vampire_offset\": -1, \"hp_max_override\": 999}', 9, 2, 1, 2, 3, 'Безответный удар.<br />\nВампиризм на X-1, где X — число ран, нанесенных Вампиром.'),
(140, 'Ведьма слуа', 's1_140', 'f6391', 1, 5, 4, 5, 0, 0, 'Слуа', 'creature', 'common', '{\"actions\": [{\"key\": \"blood_tap\", \"name\": \"Кровавый разряд\", \"type\": \"blood_tap\", \"base_hp\": 8, \"max_extra\": 4}], \"vampire\": true, \"hp_max_override\": 12}', 8, 2, 2, 2, 3, 'Вампиризм. Максимум 12 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Снимите X дополнительных жизней с Ведьмы слуа, при этом — разряд на X.'),
(141, 'Моровой всадник', 's1_141', 'e95ae', 1, 5, 4, 5, 0, 0, 'Нежить', 'creature', 'common', '{\"armor\": {\"value\": 1}, \"incarnation\": {\"open\": true, \"turns\": 3, \"abilities\": {\"ova\": 2, \"ability_strike\": 2}}}', 7, 2, 2, 3, 3, 'Инкарнация 3.<br />\r\nИнкарнирует в открытом виде, при этом получает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">2 и +2 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца хода.'),
(142, 'Суккуб-истязатель', 's1_142', 'e8480', 1, 5, 4, 4, 0, 1, 'Демон', 'creature', 'common', '{\"actions\": [{\"key\": \"discharge1\", \"type\": \"discharge\", \"value\": 1, \"all_rows_bonus\": 3}]}', 7, 2, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1. +3 к разряду, если в каждом ряду поля боя есть ваше существо.'),
(143, 'Возница', 's1_143', 'e09c3', 1, 5, 5, 5, 0, 0, 'Демон', 'creature', 'common', '{\"row_extreme\": true}', 10, 2, 3, 3, 3, 'Возница может перемещаться между крайними клетками одного ряда как на рядом стоящую клетку. Возница может объявлять <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> с крайней клетки ряда по существу, стоящему на противоположной клетке ряда, как по рядом стоящему.'),
(144, 'Герольд мрака', 's1_144', 'a82ff', 1, 5, 5, 3, 0, 1, 'Демон', 'creature', 'uncommon', '{\"zoz\": true, \"actions\": [{\"key\": \"dissonance\", \"name\": \"Диссонанс\", \"near\": true, \"type\": \"dissonance\", \"value\": 1}]}', 9, 1, 2, 2, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «диссонанс» — ранить на 1 выбранное существо и каждое стоящее рядом с ним существо противника с таким же значением слабого <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.'),
(145, 'Демон зависти', 's1_145', 'f99e3', 1, 5, 5, 2, 0, 0, 'Демон', 'creature', 'uncommon', '{\"ability\": {\"only\": [\"strike\"], \"value\": 1, \"condition\": {\"type\": \"enemies_near\", \"count\": 2, \"weak_min\": 3}}, \"actions\": [{\"key\": \"teleport\", \"name\": \"Телепортация\", \"type\": \"jump\", \"range\": 99}, {\"key\": \"envy_magic\", \"name\": \"Магический удар\", \"type\": \"magic\", \"value\": 3, \"condition\": {\"type\": \"enemies_near\", \"count\": 2, \"has_magic\": true}}]}', 10, 1, 2, 2, 3, 'Телепортация.<br />\n+1 к ударам, пока стоит рядом с двумя существами противника со значением слабого <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> 3 или больше.<br />\nПолучает «<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 3», пока стоит рядом с двумя или более существами противника, обладающими разрядом, магическим ударом или заклинанием.'),
(146, 'Керсамская знать', 's1_146', 'cc878', 1, 5, 5, 4, 0, 1, 'Слуа', 'creature', 'uncommon', NULL, 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «буря крови» — получить дополнительную <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">, затем ранить выбранное существо на X, где X — количество выших карт, у которых количество текущих <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> больше начального значения <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> (максимум 3).'),
(147, 'Повелитель мертвых', 's1_147', 'df4fb', 1, 5, 5, 4, 0, 1, '', 'creature', 'uncommon', '{\"instants\": [{\"key\": \"bone\", \"name\": \"Кость\", \"effect\": {\"type\": \"damage\", \"value\": 1}, \"target\": \"enemy\", \"trigger\": \"turn\"}]}', 7, 1, 2, 2, 3, 'При инкарнации вашего существа Повелитель мертвых может открыться.<br />\nПри инкарнации вашего существа оно получает +1 к <img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\"> до конца вашего следующего хода.<br />\n<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «кости» на 1, дальность 4.'),
(148, 'Сшиватель плоти', 's1_148', 'af56e', 1, 5, 5, 5, 0, 1, '', 'creature', 'rare', NULL, 8, 1, 1, 2, 2, '3<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Изгнать существо с вашего кладбища, при этом возродить ваше нелетающее существо, оно теряет особенности и получает +X к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и +Y к <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">, где X — значение слабого <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, а Y — значение <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> изгнанного существа (1 раз за бой).<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечить темное существо на 1, при этом получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(149, 'Талион', 's1_149', 'b4cd1', 1, 5, 5, 4, 0, 0, 'Нежить', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"armor\": {\"value\": 1}, \"incarnation\": 4, \"on_strong_strike\": {\"type\": \"incarnation_token_graveyard\"}}', 9, 1, 2, 3, 5, 'Инкарнация 4.<br />\nПри сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — положите жетон инкарнации на существо на вашем кладбище.'),
(150, 'Харон', 's1_150', 'd80b2', 1, 5, 5, 4, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"key\": \"last_journey\", \"name\": \"Последний путь\", \"type\": \"destroy_self_and_target\", \"coins\": 3, \"target\": \"any_creature\"}, {\"type\": \"discharge\", \"value\": 1}], \"save_coins\": true}', 8, 1, 1, 1, 2, '3<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «последний путь» — уничтожить Харона и выбранное существо.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1.'),
(151, 'Зомби', 's1_151', 'cbfa0', 1, 5, 6, 3, 0, 0, 'Нежить', 'creature', 'common', '{\"direct\": true, \"ability\": {\"max\": 2, \"only\": [\"strike\"], \"value\": 1, \"per_ally\": {\"element\": \"dark\"}}}', 11, 1, 1, 2, 2, '+X к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> (максимум +2), где X — число других темных существ в вашем отряде.'),
(152, 'Пещерник', 's1_152', 'd2b12', 1, 5, 6, 4, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"type\": \"uchr\", \"value\": 2}, {\"key\": \"heal_self\", \"self\": true, \"type\": \"heal\", \"value\": 3}]}', 8, 2, 2, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 2.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечиться на 3.'),
(153, 'Сайкорон', 's1_153', 'a0349', 1, 5, 6, 4, 0, 0, 'Демон', 'creature', 'common', NULL, 10, 1, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Магический удар на 2-3-4.<br />\nПри дальней атаке по существу, стоящему рядом с Сайкороном — он может телепортироваться на свободную клетку рядом с атаковавшим (1 раз за бой).'),
(154, 'Мрачная дворянка', 's1_154', 'e46a4', 1, 5, 7, 5, 0, 1, 'Слуа', 'creature', 'rare', NULL, 8, 2, 2, 3, 5, 'Вампиризм. Максимум 12 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">.<br />\nПока у Мрачной дворянки больше 8 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> — может блокировать первое за ход излечениие карты противника.<br />\nПока у Мрачной дворянки меньше 8 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> — может удвоить первое за ход излечение вашей карты.'),
(155, 'Рогатый демон', 's1_155', 'edaa0', 1, 5, 7, 5, 0, 0, 'Демон', 'creature', 'uncommon', '{\"zoo\": true, \"zov\": true, \"zoal\": true, \"actions\": [{\"key\": \"teleport\", \"name\": \"Телепортация\", \"type\": \"jump\", \"range\": 99}], \"vampire\": true, \"hp_max_override\": 12}', 7, 1, 2, 2, 3, 'Телепортация.<br />\nВампиризм. Максимум 12 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">.'),
(156, 'Метаморф', 's1_156', 'fa62a', 1, 5, 4, 4, 1, 0, '', 'creature', 'common', '{\"direct\": true, \"copy_target_strike\": true}', 9, 2, 0, 0, 0, '+X к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, где X — значение <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> атакованного существа (без учета модификаторов).'),
(157, 'Лунная баньши', 's1_157', 'a4137', 1, 5, 5, 3, 1, 1, 'Нежить', 'creature', 'uncommon', '{\"actions\": [{\"type\": \"tap\", \"coins\": 1, \"value\": 1}], \"instants\": [{\"key\": \"krik\", \"name\": \"Крик баньши\", \"effect\": {\"mode\": \"reduce_one\", \"type\": \"strike_level\"}, \"trigger\": \"combat\", \"phase\": \"value\"}]}', 7, 1, 1, 1, 2, '[Эррата 2023.04.08]<br />\r\n<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «крик Баньши» — уменьшить величину выбранного удара на 1, при этом получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\r\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «ужас» — существо противника, которое не получало ран от атак в этот ход, получает -3 к <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> до конца хода.<br />\r\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Начинает бой с <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(158, 'Уордак', 's1_158', 'dad36', 1, 5, 5, 3, 1, 0, '', 'creature', 'common', '{\"ova\": {\"value\": 1}, \"ability\": {\"only\": [\"strike\"], \"level\": [\"strong\"], \"value_from\": \"target_hp_half\"}, \"deadeat\": true}', 12, 2, 2, 3, 0, 'Трупоедство.<br />\n+X к сильному <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, где X — половина текущих <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> атакованного существа (при нечетном количестве текущих <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> округлять их в меньшую сторону).'),
(159, 'Драккарх', 's1_159', 'e6c40', 1, 5, 6, 3, 1, 1, 'Дракон', 'fly', 'uncommon', '{\"zoo\": true, \"ability\": {\"only\": [\"strike\"], \"value\": 1, \"target_type\": \"fly\"}, \"actions\": [{\"key\": \"get_direct\", \"name\": \"Получить направку\", \"self\": true, \"type\": \"tap\", \"grant_modifier\": {\"stat\": \"direct\", \"value\": true}}], \"damage_reduction\": [{\"types\": [\"shot\", \"throw\", \"discharge\"], \"value\": 1}]}', 9, 0, 2, 3, 3, '-1 от дальних атак.<br />\r\n+1 <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по летающим.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Получить <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\">.'),
(160, 'Лилит и Эйдерик', 's1_160', 'a9510', 1, 5, 6, 4, 1, 1, 'Демон, Нежить', 'creature', 'ultrarare', NULL, 7, 1, 2, 2, 3, 'В начале вашего хода положите верхнюю карту колоды на кладбище; если это демон — положите жетон инкарнации на вашу карту нежити на кладбище, если это нежить — ваши демоны получают +1 к сильному <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 или +1 к <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\"> до конца хода.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1, метание на 1 (по разным картам).'),
(161, 'Скелетный червь', 's1_161', 'a64e4', 1, 5, 6, 5, 1, 0, 'Нежить', 'creature', 'rare', NULL, 10, 2, 2, 3, 4, 'Инкарнация 4. При попадании на кладбище – выбранная клетка получает маркер «дрожь» (один раз за бой). В начале хода противника, если скелетный червь на кладбище — может переместить «дрожь» на 1 клетку. Инкарнирует только на клетке с «дрожью», в открытом виде (если клетка занята, то уничтожить все карты на ней), при этом убрать эту «дрожь»; ранить все стоящие рядом карты на 1.'),
(162, 'Тварь', 's1_162', 'ce56e', 1, 5, 6, 3, 1, 0, '', 'creature', 'rare', NULL, 10, 2, 2, 3, 4, 'Трупоедство.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Положить маркер «удушения» на стоящее рядом рядовое существо (существо с одним маркером не может передвигаться, с двумя — также не может атаковать, с тремя — уничтожиется Тварью; удушаемое существо теряет маркеры, если рядом с ним нет Тварей протвника).'),
(163, 'Хозяин склепа', 's1_163', 'c793e', 1, 5, 6, 4, 1, 1, 'Нежить', 'creature', 'rare', '{\"coins\": {\"max_value\": 3}, \"actions\": [{\"key\": \"skull\", \"name\": \"Метание черепа\", \"type\": \"throw\", \"range\": 5, \"value\": 1, \"coin_bonus\": 2, \"reset_coins_after\": true}], \"save_coins\": true, \"on_any_death\": {\"side\": \"any\", \"cause\": \"any\", \"value\": 1, \"effect\": \"get_coin\", \"filter\": \"not_flying\"}}', 8, 1, 2, 2, 3, 'При гибели нелетающего существа — получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">. Не может иметь более 3 <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Метание «черепа» на 1, дальность 5. +2 к метанию за каждую <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> на Хозяине склепа. При метании — теряет все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(164, 'Поганище', 's1_164', 'a1883', 1, 5, 7, 3, 1, 0, 'Нежить', 'creature', 'common', NULL, 12, 1, 3, 4, 5, 'Инкарнация 3. Неповоротливость.<br />\nПри получении жетона инкарнации – ранить X карт на 1, где X – число жетонов инкарнации на Поганище (воздействие «могильная хватка»).'),
(165, 'Барака', 's1_165', 'bd73e', 1, 5, 7, 4, 1, 0, 'Нежить', 'creature', 'common', '{\"ovz\": {\"value\": 1}, \"no_close_after_attack\": true}', 13, 1, 3, 4, 4, 'После нападения не закрывается.'),
(166, 'Вурдалак', 's1_166', 'd6321', 1, 5, 7, 3, 1, 0, 'Слуа', 'creature', 'uncommon', '{\"ova\": {\"value\": 1}, \"vampire\": true, \"vampire_offset\": -1, \"hp_max_override\": 13, \"damage_reduction\": [{\"types\": [\"shot\", \"throw\", \"discharge\"], \"value\": 1}]}', 13, 2, 3, 3, 4, '-1 от дальних атак.<br />\nВамриризм. Максимум 13 <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\">.'),
(167, 'Мерцающий змей', 's1_167', 'a4bdb', 1, 5, 7, 4, 1, 1, 'Дракон', 'fly', 'rare', '{\"ova\": {\"value\": 1}, \"ranged_intercept\": [\"shot\", \"throw\"]}', 13, 0, 2, 2, 3, 'Карты противника могут объявлять выстрел и метание только по Мерцающему змею (вне зависимости от дальности).'),
(168, 'Повелитель бездны', 's1_168', 'e6223', 1, 5, 8, 5, 1, 0, 'Демон', 'creature', 'common', NULL, 15, 1, 4, 5, 6, 'При гибели существа противника или инкарнации вашего существа — следующий бросок кубика Повелителя бездны равен 6.<br />\nПри перемещении на соседнюю клетку — ранить на 1 всех стоящих рядом с этой клеткой существ стоимостью 4 или менее.'),
(169, 'Властелин хаоса', 's1_169', 'f148e', 1, 5, 9, 5, 1, 1, '', 'creature', 'ultrarare', NULL, 14, 1, 4, 5, 7, 'Когда Властелин хаоса закрыт, он отражает <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> как открытая карта.<br />\r\nЗащита от слабых <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечиться на 2.'),
(170, 'Демон жадности', 's1_170', 'd7baf', 1, 5, 9, 4, 1, 1, 'Демон', 'creature', 'ultrarare', '{\"zor\": true, \"opponent_turn_end\": [{\"type\": \"greed_teleport\", \"damage\": 2, \"self_damage\": 3}], \"opponent_turn_start\": [{\"type\": \"place_gates\", \"count\": 3}]}', 16, 1, 3, 4, 6, 'В начале хода противника положите маркеры «врата» на три свободные клетки (сохраняются до конца хода противника). В конце хода противника обязан телепортироваться на любую свободную клетку с «вратами», при этом ранить всех стоящих рядом существ противника на 2; если не может переместиться — получает 3 раны.'),
(171, 'Мародер', 's1_171', 'ea38d', 1, 6, 3, 2, 0, 1, '', 'creature', 'common', '{\"deal\": {\"resource_modifier\": {\"elite_gold\": 1}}, \"actions\": [{\"type\": \"uchr\", \"value\": 1}]}', 5, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\nПри наборе Мародера в отряд вы получаете 1 <img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\">.'),
(172, 'Ведающий запасами', 's1_172', 'e1d18', 1, 6, 4, 1, 0, 1, 'Пират', 'creature', 'uncommon', '{\"deal\": {\"cost_modifier\": {\"free_if_squad_has_costs\": [3, 4, 5, 6, 7, 8]}}}', 7, 1, 2, 2, 3, 'При наборе отряда, если в вашем отряде есть карты стоимостью 3, 4, 5, 6, 7 и 8, вы можете взять Ведающего запасами в отряд бесплатно.'),
(173, 'Ведунья Ордена', 's1_173', 'af737', 1, 6, 4, 5, 0, 0, 'Инквизитор', 'creature', 'common', '{\"ova\": {\"value\": 1}}', 7, 1, 1, 1, 2, 'В конце хода противника вы можете посмотреть 3 верхние карты вашей колоды, затем положить их на верх или в низ вашей колоды в любом порядке, не перемешивая колоду.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1, дальность 4.'),
(174, 'Взрывная Мэри', 's1_174', 'c57f0', 1, 6, 4, 3, 0, 1, 'Пират', 'creature', 'common', '{\"instants\": [{\"key\": \"pirate_valor\", \"name\": \"Пиратская удаль\", \"effect\": {\"type\": \"damage\", \"value\": 1}, \"target\": \"enemy\", \"trigger\": \"turn\"}, {\"key\": \"black_mark\", \"name\": \"Чёрная метка\", \"effect\": {\"type\": \"damage_on_dice\", \"value\": 1, \"damage\": 2}, \"trigger\": \"combat\", \"phase\": \"dice\"}]}', 8, 1, 1, 2, 3, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «черная метка» — когда бросок кубика существа равен 1 — ранить его на 2.<br />\n<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «пиратская удаль» — ранить существо противника на 1.'),
(175, 'Крондак', 's1_175', 'f5e0f', 1, 6, 4, 4, 0, 0, 'Инквизитор', 'creature', 'common', '{\"actions\": [{\"key\": \"bonfire\", \"name\": \"Разжигание костра\", \"type\": \"place_cell_marker\", \"marker\": \"bonfire\", \"duration\": \"end_of_opponent_turn\"}, {\"key\": \"discharge\", \"name\": \"Разряд\", \"type\": \"discharge\", \"value\": 1, \"flying_bonus\": 1}]}', 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «разжигание костра» — положите маркер «костра» на свободную клетку (до конца хода противника), клетка с маркером «костра» считается занятой.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1. +1 к разряду по летающим.'),
(176, 'Наемник', 's1_176', 'e99f0', 1, 6, 4, 5, 0, 1, '', 'creature', 'ultrarare', '{\"ovz\": {\"value\": 1}, \"damage_reduction\": [{\"line\": true, \"types\": [\"shot\", \"throw\"], \"value\": 1}]}', 10, 1, 3, 3, 4, 'Строй: -1 от выстрелов и метаний.'),
(177, 'Следопыт', 's1_177', 'd334a', 1, 6, 4, 4, 0, 0, '', 'creature', 'uncommon', NULL, 8, 2, 1, 1, 2, 'После расстановки карт вскройте Следопыта — противник вскрывает карты своего первого ряда, а вы можете поменять расположение своих карт на вашей половине поля боя, не вскрывая их.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1.');
INSERT INTO `cards` (`ind`, `name`, `ukid`, `code`, `release_id`, `element_id`, `price`, `power`, `elite`, `single`, `class`, `type`, `rarity`, `prop`, `health`, `move`, `strike_weak`, `strike_medium`, `strike_strong`, `descr`) VALUES
(178, 'Алвалинд', 's1_178', 'badac', 1, 6, 5, 4, 0, 1, 'Инквизитор', 'creature', 'rare', '{\"turn_end\": [{\"type\": \"discharge\", \"value\": 1}]}', 8, 1, 1, 2, 3, 'При промахе вашего существа в ваш ход — получить <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.<br />\nКогда получает третью <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> — потерять все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">, при этом получить 2 раны (воздействие «все пропало»).<br />\nВ конце вашего хода — разряд на 1 (+2 к разряду за каждую <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">), при этом теряет все <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\">.'),
(179, 'Жжраг', 's1_179', 'f07e3', 1, 6, 5, 4, 0, 0, '', 'creature', 'common', '{\"deadeat\": true, \"deadeat_hp_bonus\": 3}', 10, 1, 2, 2, 3, 'Трупоедство.<br />\nПри трупоедстве получает 3 дополнительные жизни.'),
(180, 'Линнет', 's1_180', 'a7e8b', 1, 6, 5, 4, 0, 1, 'Инквизитор', 'creature', 'ultrarare', '{\"zom\": true, \"deal\": {\"linked_recruit\": {\"max_elite_cost\": 7, \"requires_empty_squad\": true, \"companion_payment_resource\": \"silver\"}}, \"actions\": [{\"name\": \"Разряд\", \"type\": \"discharge\", \"strike\": {\"weak\": 1, \"medium\": 1, \"strong\": 2}}], \"damage_reduction\": [{\"types\": [\"shot\", \"throw\"], \"value\": 1}]}', 8, 1, 1, 2, 3, '-1 от дальних атак.<br />\nДо набора отряда вы можете показать Линнет и существо стоимостью не больше 7<img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\">; возьмите Линнет и это существо в отряд за <img src=\"/images/icons/icon-ordinary.png\" class=\"img-fluid\" alt=\"ordinary\">, это существо получает особенность «Погибает, когда ваша Линнет покидает поле боя».<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Разряд на 1-1-2.'),
(181, 'Ловец удачи', 's1_181', 'ba145', 1, 6, 5, 5, 0, 1, '', 'creature', 'common', '{\"actions\": [{\"type\": \"uchr\", \"value\": 1}], \"instants\": [{\"key\": \"udacha\", \"name\": \"Удача\", \"effect\": {\"type\": \"dice_choice\"}, \"trigger\": \"combat\", \"phase\": \"dice\"}], \"open_on_opponent_turn\": true}', 8, 1, 1, 2, 3, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1<br />\n<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Воздействие «удача» — +1 или -1 к броску кубика, или перебросить кубик.<br />\nВ начале хода противника может открыться.'),
(182, 'Матросы Аделаиды', 's1_182', 'a9cf8', 1, 6, 5, 3, 0, 0, 'Пират', 'creature', 'common', NULL, 8, 1, 2, 2, 3, 'Прыжок, дальность 3.<br />\nПолучает <img src=\"/images/icons/icon-ovz.png\" class=\"img-fluid\" alt=\"ovz\">1 и -1 от слабых <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, пока стоит в центральном столбце.<br />\nПолучает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 и +1 к среднему и сильному <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, пока стоит в крайнем левом или правом столбце.'),
(183, 'Дозор Форрендора', 's1_183', 'd1be0', 1, 6, 5, 4, 0, 0, '', 'creature', 'uncommon', NULL, 9, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Выстрел на 1. +1 к выстрелу по летаюшим существам.<br />\nПри гибели летающего существа — Дозор Форрендора может получить полет и +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> до конца боя (1 раз за бой).'),
(184, 'Отшельница', 's1_184', 'da9d4', 1, 6, 5, 3, 0, 0, '', 'creature', 'common', '{\"actions\": [{\"key\": \"heal_self\", \"name\": \"Излечение\", \"self\": true, \"type\": \"heal\", \"value\": 3}], \"instants\": [{\"key\": \"raneniya\", \"name\": \"Перераспределение ран\", \"effect\": {\"type\": \"redistribute_wounds\"}, \"trigger\": \"combat\", \"phase\": \"wounds\"}]}', 9, 1, 1, 1, 2, '<img src=\"/images/icons/icon-instant.png\" class=\"img-fluid\" alt=\"instant\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Когда существо получает раны от удара — перераспределить эти раны на других ваших существ.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Излечиться на 3.'),
(185, 'Шакси', 's1_185', 'f444e', 1, 6, 5, 3, 0, 1, '', 'creature', 'rare', NULL, 8, 1, 2, 3, 3, 'Прыжок, дальность 3. При прыжке бросьте кубик: если выпало 1 или 2 — ранить стоящее рядом существо на 2; если выпало 3 или 4 — излечить Шакси или стоящее рядом существо на 3; если выпало 5 или 6 — стоящее рядом существо получает <img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"> (воздействие «удар копытцем»).'),
(186, 'Головорез', 's1_186', 'd1312', 1, 6, 6, 4, 0, 0, 'Пират', 'creature', 'common', '{\"ova\": {\"value\": 1, \"condition\": \"more_ally_near_than_enemy\"}, \"zov\": true, \"direct\": {\"check\": true, \"condition\": \"more_ally_near_than_enemy\"}}', 12, 1, 2, 3, 4, 'Пока рядом с Головорезом больше ваших существ, чем существ противника, он получает <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 и <img src=\"/images/icons/icon-direct.png\" class=\"img-fluid\" alt=\"direct\">.'),
(187, 'Лазутчица', 's1_187', 'ddbc0', 1, 6, 6, 3, 0, 1, 'Пират', 'creature', 'common', '{\"zot\": true, \"deal\": {\"scout_recruit\": {\"reveal_count\": 2, \"discount_resource\": \"silver\", \"discount_per_elite\": 1, \"requires_empty_squad\": true, \"lock_return_after_recruit\": true}}}', 10, 2, 2, 3, 4, 'До набора отряда вы можете показать противнику Лазутчицу из своей раздачи, при этом посмотреть 2 случайные карты из раздачи противника; за каждую показанную <img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\"> карту Лазутчица стоит на 1<img src=\"/images/icons/icon-ordinary.png\" class=\"img-fluid\" alt=\"ordinary\"> меньше; вы обязаны взять ее в отряд.'),
(188, 'Паладин Алламора', 's1_188', 'cb13c', 1, 6, 6, 4, 0, 0, 'Эльф, Инквизитор', 'creature', 'common', '{\"armor\": {\"value\": 1}, \"ability\": {\"line\": true, \"only\": [\"strike\"], \"value\": 1, \"element\": \"dark\"}, \"column_range_aura\": {\"types\": [\"shot\", \"throw\", \"discharge\"], \"value\": 1, \"target\": \"ally\"}}', 10, 1, 2, 3, 4, 'Строй: +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> по темным картам.<br />\nВаши существа с выстрелом, метанием или разрядом в одном столбце с Паладином Алламора получают +1 к дальности.'),
(189, 'Воин храма', 's1_189', 'c7907', 1, 6, 8, 4, 0, 0, 'Инквизитор', 'creature', 'common', '{\"dice\": {\"types\": [\"shot\", \"throw\", \"discharge\", \"uchr\", \"strike\"], \"double\": true}, \"block\": {\"dice\": [5, 6], \"types\": [\"shot\", \"throw\", \"discharge\", \"uchr\"]}}', 13, 2, 2, 4, 6, 'Когда Воин храма сражается, бросьте кубик два раза и выберите один из результатов бросков.<br />\r\nЕсли Воин храма атакован дальней атакой — бросьте кубик; если выпало 5 или 6 — эта атака блокируется.'),
(190, 'Вольный воитель', 's1_190', 'c58b3', 1, 6, 2, 4, 1, 1, '', 'creature', 'uncommon', '{\"ova\": 1, \"deal\": {\"recruit_choice\": {\"extra_cost\": {\"max\": 4, \"min\": 0, \"resource\": \"silver\"}, \"instance_buff\": {\"health\": 2, \"attack_per_x\": 1}}}, \"armor\": {\"value\": 1}}', 3, 1, 0, 1, 2, 'При наборе Вольного воителя в отряд вы можете заплатить за него на X больше, при этом он начинает игру с +X к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> и +2 к <img src=\"/images/icons/icon-health.png\" class=\"img-fluid\" alt=\"health\"> (X не может быть больше 4).'),
(191, 'Ассасин', 's1_191', 'd7254', 1, 6, 5, 4, 1, 1, 'Койар', 'creature', 'rare', '{\"actions\": [{\"type\": \"jump\", \"range\": 3}, {\"type\": \"uchr\", \"value\": 1}, {\"near\": true, \"type\": \"execute\", \"value\": 4}]}', 7, 1, 1, 2, 3, 'Прыжок, дальность 3.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\r\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Добивание на 4.'),
(192, 'Ревнитель Сеггера', 's1_192', 'edea5', 1, 6, 5, 4, 1, 0, 'Инквизитор', 'creature', 'uncommon', NULL, 10, 1, 2, 3, 3, 'При <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> выберите число, меньшее или равное X, где X — значение этого <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, при этом ваши существа справа и слева от Ревнителя Сеггера получают защиту от немагических атак такой величины до конца следующего хода противника.'),
(193, 'Арацент', 's1_193', 'ce9de', 1, 6, 6, 5, 1, 0, '', 'creature', 'uncommon', '{\"strike_effects\": [{\"levels\": [\"weak\"], \"poison\": 1}, {\"levels\": [\"medium\", \"strong\"], \"poison\": 2}]}', 12, 2, 2, 2, 3, 'При слабом <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — атакованный получает отравление на 1.<br />\nПри среднем или сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — атакованный получает отравление на 2.'),
(194, 'Аристократка', 's1_194', 'dacbb', 1, 6, 6, 2, 1, 1, '', 'creature', 'uncommon', NULL, 7, 1, 1, 1, 2, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\r\nВ начале боя — воздействие «интриги»:<br />\r\n<img src=\"/images/icons/icon-first.png\" class=\"img-fluid\" alt=\"first\">: Два выбранных существа получают отравление на 1.<br />\r\n<img src=\"/images/icons/icon-second.png\" class=\"img-fluid\" alt=\"second\">: Закройте две карты противника, они не открываются в начале первого хода своего владельца.'),
(195, 'Берсерк', 's1_195', 'd8da8', 1, 6, 6, 5, 1, 1, '', 'creature', 'rare', '{\"ova\": {\"value\": 1}, \"zoo\": true, \"zoz\": true, \"direct\": true, \"actions\": [{\"type\": \"uchr\", \"value\": 1}], \"attacks_per_turn\": 2, \"strike_consecutive\": true, \"strike_targets_unique\": true}', 10, 1, 3, 4, 5, '<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: <img src=\"/images/icons/icon-uchr.png\" class=\"img-fluid\" alt=\"uchr\"> на 1.<br />\nМожет нападать ударом два раза за ход, только подряд и по разным картам, после первого удара не закрывается.'),
(196, 'Гермет', 's1_196', 'd4466', 1, 6, 6, 3, 1, 0, '', 'creature', 'uncommon', NULL, 10, 1, 2, 3, 4, 'В начале боя получает:<br />\n+1 к <img src=\"/images/icons/icon-move.png\" class=\"img-fluid\" alt=\"move\">, если у вас есть степное существо;<br />\n<img src=\"/images/icons/icon-armor.png\" class=\"img-fluid\" alt=\"armor\">1, если у вас есть горное существо;<br />\n<img src=\"/images/icons/icon-regen.png\" class=\"img-fluid\" alt=\"regen\">1, если у вас есть болотное существо;<br />\n<img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 и <img src=\"/images/icons/icon-ovz.png\" class=\"img-fluid\" alt=\"ovz\">1, если у вас есть лесное существо; +1 к среднему и сильному <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, если у вас есть темное существо.'),
(197, 'Эорвал', 's1_197', 'c9cb2', 1, 6, 6, 4, 1, 1, 'Дракон', 'creature', 'common', NULL, 10, 1, 2, 3, 5, 'Эорвал получает +1 к <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\">, <img src=\"/images/icons/icon-ova.png\" class=\"img-fluid\" alt=\"ova\">1 и -1 от немагических атак, пока рядом с ним стоят существа минимум 4 разных классов.'),
(198, 'Варлок', 's1_198', 'c9a0f', 1, 6, 7, 5, 1, 0, '', 'creature', 'rare', NULL, 8, 1, 1, 2, 3, '-1 от дальних атак.<br />\n<img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «пламя бездны» — ранить на 2 каждое существо противника, обладающее выстрелом, метанием или разрядом.<br />\n<img src=\"/images/icons/icon-counter.png\" class=\"img-fluid\" alt=\"counter\"><img src=\"/images/icons/icon-tap.png\" class=\"img-fluid\" alt=\"tap\">: Заклинание «дверь измерений» — переместить существо на любую незанятую клетку поля боя.'),
(199, 'Тич', 's1_199', 'dbbfe', 1, 6, 7, 3, 1, 1, 'Пират', 'creature', 'ultrarare', '{\"ova\": 1, \"zor\": true, \"deal\": {\"squad_constraint\": {\"max_elemental_cards\": 3}, \"resource_modifier\": {\"elite_gold\": 2}}, \"direct\": true, \"strike_effects\": [{\"levels\": [\"strong\"], \"wound_target_by_behind_weak_strike\": true}]}', 12, 2, 2, 3, 4, 'При наборе Тича в отряд вы можете получить 2<img src=\"/images/icons/icon-elite.png\" class=\"img-fluid\" alt=\"elite\">, при этом в вашем отряде не может быть больше трех стихийных карт.<br />\nПри сильном <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> — ранить атакованное существо на величину слабого <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> стоящей сзади него карты (воздействине «коварный подкуп»).'),
(200, 'Волот', 's1_200', 'adf84', 1, 6, 9, 4, 1, 1, '', 'creature', 'ultrarare', '{\"clumsy\": 1, \"strike\": {\"redirect\": true}}', 24, 1, 5, 6, 7, 'Неповоротливость.<br />\nПротивник может перенаправить <img src=\"/images/icons/icon-strike.png\" class=\"img-fluid\" alt=\"strike\"> Волота на любое свое существо, стоящее рядом с Волотом.');
